content.content:
    components: [{ type: 2, style: 1, label, custom_id: customId }],
  };
}

/** Post a plain message, optionally with a Reply button. */
export async function postChannelMessage(
  channelId: string,
  content: string,
  opts: { replyButtonCustomId?: string } = {},
): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}/messages`, {
    method: "POST",
    body: {
      content: content.slice(0, 2000), // Discord message content cap
      components: opts.replyButtonCustomId ? [replyButtonRow(opts.replyButtonCustomId)] : undefined,
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] postChannelMessage failed", channelId, res?.status, res?.json);
    return false;
  }
  return true;
}

/** Best-effort bot-authenticated lookup of a Discord user's public profile (for display only — e.g. showing a linked username in Settings). Returns null on ANY problem. */
export async function getDiscordUserById(userId: string): Promise<{ id: string; username: string } | null> {
  const res = await discordFetch(`/users/${userId}`);
  if (!res || res.status >= 300) return null;
  const json = res.json as { id?: unknown; username?: unknown };
  if (typeof json.id !== "string") return null;
  return { id: json.id, username: typeof json.username === "string" ? json.username : "" };
}

export async function getChannel(channelId: string): Promise<{ id: string; name: string } | null> {
  const res = await discordFetch(`/channels/${channelId}`);
  if (!res || res.status >= 300) return null;
  return res.json as { id: string; name: string };
}

export async function deleteChannel(channelId: string): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}`, { method: "DELETE" });
  return Boolean(res && res.status < 300);
}

/** Re-parent an existing channel under a different category — used both to
 *  keep newly-created ticket/chat channels organized and to archive them on
 *  close (moving them out of the active category, not deleting them). */
export async function moveChannelToCategory(channelId: string, categoryId: string): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}`, { method: "PATCH", body: { parent_id: categoryId } });
  if (!res || res.status >= 300) {
    console.error("[discord] moveChannelToCategory failed", channelId, categoryId, res?.status, res?.json);
    return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Guild provisioning (categories, richer channels, roles, permission
// overwrites, member-role assignment) — added for the community-server
// build-out. All still go through discordFetch(); none of this existed
// before, so every one of these can 403 if the bot's own guild role is
// missing MANAGE_CHANNELS (channel/category calls) or MANAGE_ROLES (role +
// permission-overwrite + member-role calls) — callers should surface a
// clear "needs a Discord permission grant" error rather than a bare 403.
// ---------------------------------------------------------------------------

/** Discord channel types relevant here: 0 text, 2 voice, 4 category. */
export const CHANNEL_TYPE = { TEXT: 0, VOICE: 2, CATEGORY: 4 } as const;

/** A handful of named permission bits (Discord bitfields are strings — can exceed 32-bit safe int). */
export const PERMISSION_BIT = {
  VIEW_CHANNEL: "1024",
  SEND_MESSAGES: "2048",
  READ_MESSAGE_HISTORY: "65536",
  CONNECT: "1048576",
  SPEAK: "2097152",
  MANAGE_ROLES: "268435456",
  MANAGE_CHANNELS: "16",
} as const;

/** A channel/category permission overwrite — `type: 0` = role, `type: 1` = member. */
export type PermissionOverwrite = { id: string; type: 0 | 1; allow?: string; deny?: string };

function safeChannelName(name: string): string {
  return (
    name
      .toLowerCase()
      .replace(/[^a-z0-9-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 90) || "channel"
  );
}

/** List every channel/category in the configured guild — used for idempotent "does this already exist" checks. */
export async function listGuildChannels(): Promise<
  Array<{ id: string; name: string; type: number; parent_id: string | null }> | null
> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  const res = await discordFetch(`/guilds/${guildId}/channels`);
  if (!res || res.status >= 300) return null;
  return res.json as Array<{ id: string; name: string; type: number; parent_id: string | null }>;
}

/** List every role in the configured guild — used for idempotent "does this already exist" checks. */
export async function listGuildRoles(): Promise<Array<{ id: string; name: string }> | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  const res = await discordFetch(`/guilds/${guildId}/roles`);
  if (!res || res.status >= 300) return null;
  return res.json as Array<{ id: string; name: string }>;
}

/** Same default-deny reasoning as createGuildTextChannel's doc comment —
 *  pass `permissionOverwrites: []` explicitly for a category that's meant
 *  to stay guild-visible (e.g. general community categories). */
export async function createGuildCategory(
  name: string,
  permissionOverwrites?: PermissionOverwrite[],
): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  // Unlike GUILD_TEXT, categories accept arbitrary names (emoji, spaces,
  // mixed case) — only length-cap, don't run it through safeChannelName.
  const res = await discordFetch(`/guilds/${guildId}/channels`, {
    method: "POST",
    body: {
      name: name.slice(0, 100),
      type: CHANNEL_TYPE.CATEGORY,
      permission_overwrites:
        permissionOverwrites ?? [{ id: guildId, type: 0, deny: PERMISSION_BIT.VIEW_CHANNEL, allow: "0" }],
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] createGuildCategory failed", res?.status, res?.json);
    return null;
  }
  return (res.json as { id: string }).id;
}

/** General channel creator (text or voice), optionally parented + with initial permission overwrites. */
export async function createGuildChannel(opts: {
  name: string;
  type: 0 | 2;
  parentId?: string;
  topic?: string;
  permissionOverwrites?: PermissionOverwrite[];
}): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  // Only GUILD_TEXT enforces the lowercase-hyphen convention — voice channel
  // names accept arbitrary text (emoji, spaces, mixed case) same as categories.
  const res = await discordFetch(`/guilds/${guildId}/channels`, {
    method: "POST",
    body: {
      name: opts.type === CHANNEL_TYPE.TEXT ? safeChannelName(opts.name) : opts.name.slice(0, 100),
      type: opts.type,
      parent_id: opts.parentId,
      topic: opts.type === CHANNEL_TYPE.TEXT ? opts.topic?.slice(0, 1024) : undefined,
      permission_overwrites: opts.permissionOverwrites,
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] createGuildChannel failed", opts.name, res?.status, res?.json);
    return null;
  }
  return (res.json as { id: string }).id;
}

/** Set (create/replace) a single permission overwrite on an existing channel. Requires MANAGE_ROLES. */
export async function setChannelPermissionOverwrite(
  channelId: string,
  overwrite: PermissionOverwrite,
): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}/permissions/${overwrite.id}`, {
    method: "PUT",
    body: { type: overwrite.type, allow: overwrite.allow ?? "0", deny: overwrite.deny ?? "0" },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] setChannelPermissionOverwrite failed", channelId, res?.status, res?.json);
    return false;
  }
  return true;
}

/** Create a guild role. `color` is a decimal RGB int (e.g. 0x6f47f5). Requires MANAGE_ROLES. */
export async function createGuildRole(opts: {
  name: string;
  color?: number;
  hoist?: boolean;
  mentionable?: boolean;
}): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  const res = await discordFetch(`/guilds/${guildId}/roles`, {
    method: "POST",
    body: {
      name: opts.name.slice(0, 100),
      color: opts.color,
      hoist: opts.hoist ?? false,
      mentionable: opts.mentionable ?? false,
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] createGuildRole failed", opts.name, res?.status, res?.json);
    return null;
  }
  return (res.json as { id: string }).id;
}

/** Grant a role to a guild member. Requires MANAGE_ROLES, and the bot's own role must sit above `roleId`. */
export async function addMemberRole(userId: string, roleId: string): Promise<boolean> {
  const guildId = await discordGuildId();
  if (!guildId) return false;
  const res = await discordFetch(`/guilds/${guildId}/members/${userId}/roles/${roleId}`, { method: "PUT" });
  if (!res || res.status >= 300) {
    console.error("[discord] addMemberRole failed", userId, roleId, res?.status, res?.json);
    return false;
  }
  return true;
}

/** Remove a role from a guild member. Requires MANAGE_ROLES. */
export async function removeMemberRole(userId: string, roleId: string): Promise<boolean> {
  const guildId = await discordGuildId();
  if (!guildId) return false;
  const res = await discordFetch(`/guilds/${guildId}/members/${userId}/roles/${roleId}`, { method: "DELETE" });
  if (!res || res.status >= 300) {
    console.error("[discord] removeMemberRole failed", userId, roleId, res?.status, res?.json);
    return false;
  }
  return true;
}

/**
 * Add a user to the configured guild directly (no invite link needed) using
 * an access token obtained with the `guilds.join` scope — the mechanism
 * behind "Sign in with Discord" auto-joining someone to the server. Called
 * as the BOT (Authorization: Bot ..., same as every other call here); the
 * user's OWN access token travels in the body, not the header. Idempotent —
 * a user who's already a member is a harmless no-op (still 201/204).
 * `roleIds`, if given, are applied at join time in the same call.
 */
export async function joinGuildWithAccessToken(userId: string, userAccessToken: string, roleIds?: string[]): Promise<boolean> {
  const guildId = await discordGuildId();
  if (!guildId) return false;
  const res = await discordFetch(`/guilds/${guildId}/members/${userId}`, {
    method: "PUT",
    body: { access_token: userAccessToken, roles: roleIds },
  });
  // 201 = newly added, 204 = already a member (both success).
  if (!res || (res.status !== 201 && res.status !== 204)) {
    console.error("[discord] joinGuildWithAccessToken failed", userId, res?.status, res?.json);
    return false;
  }
  return true;
}

/** Read the bot's own member row (roles[]) in the configured guild — used to pre-flight permission checks before provisioning. */
export async function getSelfMember(): Promise<{ userId: string; roleIds: string[] } | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  const me = await discordFetch("/users/@me");
  const botId = (me?.json as { id?: string })?.id;
  if (!botId) return null;
  const member = await discordFetch(`/guilds/${guildId}/members/${botId}`);
  if (!member || member.status >= 300) return null;
  const roles = (member.json as { roles?: string[] })?.roles ?? [];
  return { userId: botId, roleIds: roles };
}

// ---------------------------------------------------------------------------
// Interaction response helpers (used by app/api/webhooks/discord/route.ts)
// ---------------------------------------------------------------------------

/** Interaction type constants (Discord API v10). */
export const InteractionType = {
  PING: 1,
  APPLICATION_COMMAND: 2,
  MESSAGE_COMPONENT: 3,
  APPLICATION_COMMAND_AUTOCOMPLETE: 4,
  MODAL_SUBMIT: 5,
} as const;

/** Interaction callback type constants. */
export const InteractionCallbackType = {
  PONG: 1,
  CHANNEL_MESSAGE_WITH_SOURCE: 4,
  MODAL: 9,
} as const;

/** Build the modal-open response body for a "Reply" button click. */
export function replyModalResponse(customId: string, title = "Reply to customer") {
  return {
    type: InteractionCallbackType.MODAL,
    data: {
      custom_id: customId,
      title,
      components: [
        {
          type: 1,
          components: [
            {
              type: 4, // TEXT_INPUT
              custom_id: "reply_text",
              style: 2, // paragraph
              label: "Your reply",
              required: true,
              max_length: 4000,
            },
          ],
        },
      ],
    },
  };
}

/** Build the modal-open response body for the /support command — a linked
 *  customer opening a new ticket without leaving Discord. */
export function newTicketModalResponse() {
  return {
    type: InteractionCallbackType.MODAL,
    data: {
      custom_id: "dc_new_ticket_modal",
      title: "Open a support ticket",
      components: [
        {
          type: 1,
          components: [
            { type: 4, custom_id: "ticket_subject", style: 1 /* short */, label: "Subject", required: true, max_length: 150 },
          ],
        },
        {
          type: 1,
          components: [
            { type: 4, custom_id: "ticket_body", style: 2 /* paragraph */, label: "What's going on?", required: true, max_length: 4000 },
          ],
        },
      ],
    },
  };
}

/** Build a simple, visible channel-message acknowledgement response body. */
export function channelMessageResponse(content: string) {
  return {
    type: InteractionCallbackType.CHANNEL_MESSAGE_WITH_SOURCE,
    data: { content: content.slice(0, 2000) },
  };
}

/** Same as channelMessageResponse but visible ONLY to the invoking user — for
 *  the /status command, which returns account-specific server data. */
export function ephemeralMessageResponse(content: string) {
  return {
    type: InteractionCallbackType.CHANNEL_MESSAGE_WITH_SOURCE,
    data: { content: content.slice(0, 2000), flags: 64 /* EPHEMERAL */ },
  };
}

/** Extract the single text-input value from a MODAL_SUBMIT interaction payload. */
export function extractModalText(interaction: unknown): string {
  try {
    const data = (interaction as { data?: { components?: unknown[] } }).data;
    const row = data?.components?.[0] as { components?: { value?: unknown }[] } | undefined;
    const value = row?.components?.[0]?.value;
    return typeof value === "string" ? value : "";
  } catch {
    return "";
  }
}

/** Extract EVERY text-input value from a MODAL_SUBMIT payload, keyed by each
 *  field's own custom_id — for modals with more than one input (e.g. the
 *  /support "new ticket" modal's subject + description), where
 *  extractModalText's "just take components[0][0]" isn't enough. */
export function extractModalFields(interaction: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    const rows = (interaction as { data?: { components?: unknown[] } }).data?.components ?? [];
    for (const row of rows as { components?: { custom_id?: unknown; value?: unknown }[] }[]) {
      for (const field of row.components ?? []) {
        if (typeof field.custom_id === "string" && typeof field.value === "string") {
          out[field.custom_id] = field.value;
        }
      }
    }
  } catch {
    // fall through to whatever was collected
  }
  return out;
}

/**
 * Extract the REAL Discord user id of whoever triggered an interaction
 * (button click or modal submit), for reply-attribution
 * (lib/discord-bridge.ts's `submitDiscordReply`).
 *
 * This bridge only ever operates inside ONE guild, so a guild interaction's
 * `member.user.id` is the field that is actually always present — `user.id`
 * (top-level) is Discord's DM-interaction shape and would be undefined here,
 * but is checked as a harmless fallback in case that ever changes. Both
 * fields are sent and Ed25519-signed by Discord itself (verified by
 * `verifyDiscordSignature` BEFORE this is ever called), so once signature
 * verification has passed, this id is trustworthy — it cannot be spoofed by
 * the Discord user who clicked the button.
 */
export function extractInteractionUserId(interaction: unknown): string | null {
  try {
    const i = interaction as { member?: { user?: { id?: unknown } }; user?: { id?: unknown } };
    const guildUserId = i.member?.user?.id;
    if (typeof guildUserId === "string" && guildUserId) return guildUserId;
    const dmUserId = i.user?.id;
    if (typeof dmUserId === "string" && dmUserId) return dmUserId;
    return null;
  } catch {
    return null;
  }
}

import "server-only";
import { createPublicKey, verify as cryptoVerify } from "node:crypto";
import { getSetting, getSettingBool } from "./settings";
import { decryptSecret } from "./crypto-box";

/**
 * Thin Discord REST + Interactions-verification layer for the Nxeon support
 * bridge (lib/discord-bridge.ts). Deliberately NOT a discord.js Gateway
 * client and NOT a long-running process: this bot only ever (a) makes plain
 * REST calls the platform's own server code triggers, and (b) answers
 * Discord's HTTP "Interactions Endpoint" POSTs (button clicks, modal
 * submits) via app/api/webhooks/discord/route.ts. See the research this
 * build executed: an HTTP-only bot is the right shape for this codebase's
 * existing poll/request-response architecture, and Discord forum channels
 * cannot have private threads anyway (irrelevant here since the bridge uses
 * plain text channels — see lib/discord-bridge.ts for that call).
 *
 * Every config value is read via getSetting/getSettingBool/decryptSecret —
 * NEVER a bare process.env.DISCORD_* — except as a secondary fallback
 * mirroring the exact convention lib/kb-llm.ts's resolveBotKey() already
 * established for kb_bot_api_key.
 */

const DISCORD_API_BASE = "https://discord.com/api/v10";

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

export async function discordEnabled(): Promise<boolean> {
  return getSettingBool("discord_enabled", false);
}

export async function discordApplicationId(): Promise<string> {
  const v = (await getSetting("discord_application_id", "")).trim();
  return v || (process.env.DISCORD_APPLICATION_ID ?? "").trim();
}

export async function discordGuildId(): Promise<string> {
  const v = (await getSetting("discord_guild_id", "")).trim();
  return v || (process.env.DISCORD_GUILD_ID ?? "").trim();
}

export async function discordPublicKey(): Promise<string> {
  const v = (await getSetting("discord_public_key", "")).trim();
  return v || (process.env.DISCORD_PUBLIC_KEY ?? "").trim();
}

/** Decrypt-on-read, mirroring lib/kb-llm.ts's resolveBotKey() exactly. */
export async function discordBotToken(): Promise<string | null> {
  const enc = await getSetting("discord_bot_token", "");
  const own = decryptSecret(enc || null);
  if (own && own.trim()) return own.trim();
  const platform = process.env.DISCORD_BOT_TOKEN;
  return platform && platform.trim() ? platform.trim() : null;
}

/**
 * RETIRED — no longer read anywhere. See the doc comment on
 * `discord_reply_as_user_id` in lib/settings.ts for why: real per-Discord-user
 * identity linking (`User.discordUserId`) replaced this single-owner stand-in,
 * with no silent fallback. Left in place only so nothing that still imports it
 * (there should be nothing) breaks; do not add a new caller.
 */
export async function discordReplyAsUserId(): Promise<string> {
  return (await getSetting("discord_reply_as_user_id", "")).trim();
}

/**
 * OAuth2 client secret for the staff Discord-account-linking flow (decrypt-on-
 * read, mirroring `discordBotToken()` above exactly). Used ONLY by
 * lib/discord-oauth.ts's token-exchange call — never logged, never sent to the
 * browser.
 */
export async function discordClientSecret(): Promise<string | null> {
  const enc = await getSetting("discord_client_secret", "");
  const own = decryptSecret(enc || null);
  return own && own.trim() ? own.trim() : null;
}

// ---------------------------------------------------------------------------
// Ed25519 interaction-signature verification
// ---------------------------------------------------------------------------

// The fixed 12-byte ASN.1 prefix for an Ed25519 SubjectPublicKeyInfo (SPKI)
// DER structure — "SEQUENCE { SEQUENCE { OID 1.3.101.112 } BIT STRING }".
// Discord (like most Ed25519 key issuers) hands out only the raw 32-byte
// public key as hex; Node's `crypto.createPublicKey` needs a full SPKI DER
// blob to build a KeyObject, and this prefix is constant for every Ed25519
// key, so prepending it to the raw 32 bytes reconstructs a valid SPKI DER
// value Node can parse. Verified against Node 22's `node:crypto` directly
// (generateKeyPairSync("ed25519") → export raw pub → reconstruct via this
// prefix → verify() succeeds and correctly rejects a tampered payload).
const ED25519_SPKI_DER_PREFIX = Buffer.from("302a300506032b6570032100", "hex");

function ed25519PublicKeyFromHex(hex: string) {
  const raw = Buffer.from(hex, "hex");
  if (raw.length !== 32) throw new Error(`Discord public key must decode to 32 bytes, got ${raw.length}`);
  return createPublicKey({
    key: Buffer.concat([ED25519_SPKI_DER_PREFIX, raw]),
    format: "der",
    type: "spki",
  });
}

/**
 * Verify a Discord Interactions Endpoint request. Discord signs
 * `timestamp + rawBody` with Ed25519 and sends the signature + timestamp as
 * headers; this MUST be checked against the raw (pre-JSON-parse) request body
 * before trusting anything in it. Returns false on ANY problem (missing
 * headers, malformed hex, wrong-length key, bad signature, tampered body) —
 * never throws, so callers can treat "false" as the single "reject with 401"
 * signal.
 */
export function verifyDiscordSignature(args: {
  rawBody: string;
  signature: string | null | undefined;
  timestamp: string | null | undefined;
  publicKeyHex: string;
}): boolean {
  const { rawBody, signature, timestamp, publicKeyHex } = args;
  if (!signature || !timestamp || !publicKeyHex) return false;
  try {
    if (!/^[0-9a-f]+$/i.test(signature) || !/^[0-9a-f]+$/i.test(publicKeyHex)) return false;
    const key = ed25519PublicKeyFromHex(publicKeyHex);
    const message = Buffer.from(timestamp + rawBody, "utf8");
    const sig = Buffer.from(signature, "hex");
    return cryptoVerify(null, message, key, sig);
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// REST client
// ---------------------------------------------------------------------------

export class DiscordApiError extends Error {
  constructor(
    public status: number,
    public body: unknown,
  ) {
    super(`Discord API ${status}: ${typeof body === "string" ? body : JSON.stringify(body)}`);
  }
}

/**
 * Bot-authenticated REST call. Respects a single 429 retry (Discord's rate
 * limits are generous at this volume — 50 req/s global — so anything beyond
 * one retry would indicate a real problem, not routine throttling). Returns
 * `null` (never throws) when the bot token isn't configured, so every caller
 * in lib/discord-bridge.ts can stay a best-effort no-op.
 */
export async function discordFetch(
  path: string,
  init: { method?: string; body?: unknown; retried?: boolean } = {},
): Promise<{ status: number; json: unknown } | null> {
  const token = await discordBotToken();
  if (!token) {
    console.error("[discord] no bot token configured — cannot call", path);
    return null;
  }
  const res = await fetch(`${DISCORD_API_BASE}${path}`, {
    method: init.method ?? "GET",
    headers: {
      Authorization: `Bot ${token}`,
      "Content-Type": "application/json",
    },
    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
  });

  if (res.status === 429 && !init.retried) {
    const retryAfterSec = Number(res.headers.get("Retry-After") ?? "1") || 1;
    await new Promise((r) => setTimeout(r, Math.min(retryAfterSec, 5) * 1000));
    return discordFetch(path, { ...init, retried: true });
  }

  const text = await res.text();
  let json: unknown = null;
  if (text) {
    try {
      json = JSON.parse(text);
    } catch {
      json = text;
    }
  }
  return { status: res.status, json };
}

// ---------------------------------------------------------------------------
// Typed helpers
// ---------------------------------------------------------------------------

/** Discord channel type 0 = GUILD_TEXT. */
const GUILD_TEXT_CHANNEL_TYPE = 0;

/**
 * `permissionOverwrites` defaults to denying @everyone VIEW_CHANNEL — a
 * brand-new private channel must never rely SOLELY on inheriting its
 * category's own permissions (see the 2026-09-05 incident: both this
 * function and createGuildCategory() created entities with zero overwrites
 * of their own, so a category whose OWN @everyone-deny was ever missing —
 * as the tickets/live-chat categories' turned out to be — silently exposed
 * every channel under it to the whole guild; grantCustomerAccessAndSummary's
 * later per-member ALLOW does nothing to restrict everyone else when there
 * was never a baseline deny). Passing `[]` explicitly opts out for a channel
 * that's deliberately meant to be guild-visible.
 */
export async function createGuildTextChannel(
  name: string,
  topic?: string,
  parentId?: string,
  permissionOverwrites?: PermissionOverwrite[],
): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) {
    console.error("[discord] no guild id configured — cannot create channel");
    return null;
  }
  // Discord channel names: lowercase, hyphens, max 100 chars, no spaces.
  const safeName = name
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 90) || "ticket";

  const res = await discordFetch(`/guilds/${guildId}/channels`, {
    method: "POST",
    body: {
      name: safeName,
      type: GUILD_TEXT_CHANNEL_TYPE,
      topic: topic?.slice(0, 1024),
      parent_id: parentId,
      permission_overwrites:
        permissionOverwrites ?? [{ id: guildId, type: 0, deny: PERMISSION_BIT.VIEW_CHANNEL, allow: "0" }],
    },
