import "server-only";
import { getSetting } from "./settings";
import { discordEnabled, postChannelMessage } from "./discord";

/**
 * Automated incident alerts -> a dedicated #status-alerts Discord channel.
 * Deliberately separate from lib/discord-bridge.ts (the ticket/chat mirror):
 * this is pure ONE-WAY notification with no reply path, no per-item channel
 * creation, and no interaction handling — posting into one fixed, pre-created
 * channel (id in the `discord_status_alerts_channel_id` setting, created once
 * alongside the guild's other categories/channels, not dynamically per
 * incident). Every StatusIncident write site (lib/actions-status.ts's manual
 * open/resolve/reopen, lib/monitoring.ts's automatic open/resolve) calls one
 * of the three functions below right after its own DB write.
 *
 * Same best-effort discipline as the rest of the Discord integration: gated
 * on `discordEnabled()`, never throws, a Discord outage or missing channel-id
 * setting must never affect the real incident-tracking write it follows.
 */

type IncidentForAlert = {
  id: string;
  component: string | null;
  severity: string;
  title: string;
  body: string;
  auto: boolean;
};

async function alertsChannelId(): Promise<string> {
  return (await getSetting("discord_status_alerts_channel_id", "")).trim();
}

const SEVERITY_EMOJI: Record<string, string> = {
  down: "🔴",
  degraded: "🟠",
  maintenance: "🔧",
};

function severityEmoji(severity: string): string {
  return SEVERITY_EMOJI[severity] ?? "⚪";
}

async function post(content: string): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const channelId = await alertsChannelId();
    if (!channelId) return;
    await postChannelMessage(channelId, content.slice(0, 2000));
  } catch (e) {
    console.error("[discord-status-alerts] post failed (non-fatal)", e);
  }
}

/** Call right after a StatusIncident is created (manual or automatic). */
export async function alertIncidentOpened(incident: IncidentForAlert): Promise<void> {
  const lines = [
    `${severityEmoji(incident.severity)} **Incident opened${incident.auto ? " (auto-detected)" : ""}: ${incident.title}**`,
    incident.component ? `**Component:** ${incident.component}` : "**Component:** platform-wide",
    `**Severity:** ${incident.severity}`,
  ];
  if (incident.body) lines.push("", incident.body);
  await post(lines.join("\n"));
}

/** Call right after a StatusIncident is resolved. */
export async function alertIncidentResolved(incident: IncidentForAlert): Promise<void> {
  await post(`✅ **Resolved: ${incident.title}**${incident.component ? ` (${incident.component})` : ""}`);
}

/** Call right after a manually-closed incident is reopened. */
export async function alertIncidentReopened(incident: IncidentForAlert): Promise<void> {
  await post(`${severityEmoji(incident.severity)} **Reopened: ${incident.title}**${incident.component ? ` (${incident.component})` : ""}`);
}
