/**
 * Register every background sweep on the SweepRunner (worker/sweeps.ts).
 *
 * Each entry used to be an inline `if (Date.now() - lastX > interval)` block
 * at the top of the claim loop; intervals and groupings are preserved exactly
 * (a group that ran as one block with ordering requirements — e.g. partner
 * commissions AFTER the renewal sweeps — stays one sweep fn). Per-sweep
 * `timeoutMs` is the budget after which the runner stops waiting and logs an
 * overrun; see the runner's doc comment for why that is not a cancel.
 *
 * Exported for the load-test harness, which registers nothing but still
 * needs the list to document what else competes for the process.
 */
export function registerSweeps(runner: SweepRunner): void {
  const m = 60_000;
  const h = 60 * m;
  const add = (name: string, intervalMs: number, fn: () => Promise<unknown>, timeoutMs?: number) =>
    runner.register({ name, intervalMs, fn, timeoutMs });

  // Backstop for the first-month-free card/Stripe HOLD (lib/promo-redemption.ts)
  // and the checkout-coupon HOLD (lib/coupon-redemption.ts): reap RESERVED
  // redemptions whose payable window has lapsed. Cheap indexed deletes.
  // Fleet private-IP audit (worker/ip-audit.ts): REPORT ONLY — duplicate IPs
  // across VM configs and DB/VM drift, logged to ErrorLog. 2026-10-02: node-2
  // had 10.20.1.101 on four VMs and nothing anywhere noticed.
  add("fleet-ip-audit", 6 * h, fleetIpAuditSweep, 10 * m);
  // Exclusive CPU reservations (worker/cpu-affinity.ts): every minute, on each node
  // with a CpuReservation, re-assert config + live-thread affinity of every VM and
  // alert if a reservation's cores were reachable by another VM. Replaces the
  // interim node-6 nxeon-cpu-reserve.timer. Also refreshes Node.cpuTopology.
  add("cpu-affinity", m, cpuAffinitySweep, 3 * m);
  // Off-site backup freshness (worker/offsite-backup-sweep.ts): inert unless NXEON_OFFSITE_FRESHNESS=1.
  add("offsite-backup-freshness", 1 * h, offsiteBackupSweep, 20 * m);
  // OVH upstream firewalls (worker/ovh-game-firewall-sweep.ts): READ-ONLY (GET) check that no node/pooled IP is in
  // game-firewall strict mode (2026-10-04: it silently dropped every UDP game on node-4) -> admin alert, auto-resolves.
  // Default on; Setting ovh_game_firewall_check_enabled=false turns it off. Failure-silent.
  add("ovh-game-firewall", 1 * h, ovhGameFirewallSweep, 6 * m);
  // OVH account (worker/ovh-account-sweep.ts): READ-ONLY (GET). Alerts when OVH antihack/spam/ARP-blocks one of
  // our IPs (names the customer server: usually a compromised VM) or a node's service nears expiry with auto-renew
  // off. Default on; Setting ovh_account_sweep_enabled=false turns it off; ovh_renewal_alert_days (default 14).
  add("ovh-account", 1 * h, ovhAccountSweep, 9 * m);
  // Dedicated-server catalogue (lib/dedicated/sync.ts): READ-ONLY public catalogue + stock GETs (no auth),
  // self-throttled to Setting dedicated_catalog_sync_hours (default 6h) or an admin "Sync now" request.
  // Fire-and-forget (a sync is ~40 MB of JSON) with its own in-flight guard; keeps last good data on failure.
  add("dedicated-catalog", m, async () => { void dedicatedCatalogTick(); });
  // Dedicated-server Phase 2 actions (worker/dedicated-jobs.ts): the ONLY place customer dedicated-server
  // upstream writes happen (reboot, rescue, reinstall/handover, rDNS, firewall, approved extra-IP orders).
  // Setting dedicated_ovh_dry_run (default true) sends nothing; NXEON_DEDICATED_OVH_MOCK=1 (non-prod) uses the fake.
  add("dedicated-jobs", 10_000, () => dedicatedJobsTick(), 60_000);
  add("promo-reservations", 2 * m, sweepExpiredReservations);
  // AI Mod Builder (private preview): advance in-flight builds from the build VM's
  // service so they finish (and the jar lands on disk) even with no page open.
  // A no-op query when nothing is building.
  add("modbuilder-sync", 20 * 1000, sweepModBuilds, 2 * m);
  add("coupon-reservations", 2 * m, sweepExpiredCouponReservations);

  // Weekly SEO audit + admin "run now" queue (self-throttled, see worker/seo-audit.ts). Fire-and-forget: a
  // multi-minute audit must never hold a sweep slot.
  add("seo-audit", m, async () => { void seoAuditTick(); });
  // IndexNow sweep (seo-002): announces new/changed sitemap URLs to Bing & co. Default OFF (Setting indexnow_sweep_enabled).
