import "server-only";
import { db } from "./db";
import { getSetting } from "./settings";
import { discordEnabled, discordFetch, discordGuildId, addMemberRole, removeMemberRole } from "./discord";

/**
 * Which Discord "customer badge" roles a Nxeon account should currently
 * hold, computed fresh from real account data every time — never cached,
 * never trusted from a prior sync. Distinct from the STAFF roles (Owner,
 * Admin, Manager, Staff, Customer Support) which are always assigned by a
 * human via Discord's own UI; this module only ever touches the five
 * customer-facing badge roles below.
 */
const BADGE_SETTING_KEYS = {
  verified: "discord_role_verified_id",
  vps: "discord_role_vps_owner_id",
  game: "discord_role_game_owner_id",
  hosting: "discord_role_hosting_id",
  partner: "discord_role_partner_id",
} as const;

type BadgeKey = keyof typeof BADGE_SETTING_KEYS;

/** Same shape as lib/actions-announcements.ts's private getUserServiceTypes — kept as its own small query here rather than exporting/importing across an unrelated feature. */
async function computeBadgeKeys(userId: string): Promise<BadgeKey[]> {
  const keys: BadgeKey[] = ["verified"]; // always granted the moment an account links
  const [hasVps, hasGame, hasHosting, partner] = await Promise.all([
    db.server.findFirst({ where: { userId, gamePlanId: null }, select: { id: true } }),
    db.server.findFirst({ where: { userId, gamePlanId: { not: null } }, select: { id: true } }),
    db.hostingAccount.findFirst({ where: { userId }, select: { id: true } }),
    db.referralPartner.findUnique({ where: { userId }, select: { id: true, status: true } }),
  ]);
  if (hasVps) keys.push("vps");
  if (hasGame) keys.push("game");
  if (hasHosting) keys.push("hosting");
  if (partner && partner.status === "ACTIVE") keys.push("partner");
  return keys;
}

/**
 * Reconcile a linked Nxeon account's Discord badge roles to match what they
 * actually have right now — adds missing ones, removes stale ones (e.g. a
 * cancelled VPS should eventually lose "VPS Owner"). Best-effort and silent,
 * matching every other bridge function's kill-switch discipline: never
 * throws, a Discord hiccup never blocks the caller (account linking, a
 * purchase, a cancellation, or the periodic worker sweep).
 */
export async function syncDiscordRoles(userId: string): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
    const user = await db.user.findUnique({ where: { id: userId }, select: { discordUserId: true } as any });
    const discordUserId = (user as any)?.discordUserId as string | null | undefined;
    if (!discordUserId) return; // not linked — nothing to sync

    const guildId = await discordGuildId();
    if (!guildId) return;

    const [desired, roleIdEntries] = await Promise.all([
      computeBadgeKeys(userId),
      Promise.all(
        (Object.keys(BADGE_SETTING_KEYS) as BadgeKey[]).map(
          async (key) => [key, await getSetting(BADGE_SETTING_KEYS[key], "")] as const,
        ),
      ),
    ]);
    const roleIdByKey = Object.fromEntries(roleIdEntries.filter(([, id]) => id)) as Partial<Record<BadgeKey, string>>;
    const managedRoleIds = new Set(Object.values(roleIdByKey));

    const member = await discordFetch(`/guilds/${guildId}/members/${discordUserId}`);
    if (!member || member.status >= 300) return; // not (or no longer) a guild member
    const currentRoleIds: string[] = (member.json as { roles?: string[] })?.roles ?? [];

    const desiredRoleIds = new Set(desired.map((k) => roleIdByKey[k]).filter((v): v is string => Boolean(v)));

    for (const roleId of desiredRoleIds) {
      if (!currentRoleIds.includes(roleId)) await addMemberRole(discordUserId, roleId);
    }
    for (const roleId of currentRoleIds) {
      if (managedRoleIds.has(roleId) && !desiredRoleIds.has(roleId)) await removeMemberRole(discordUserId, roleId);
    }
  } catch (e) {
    console.error("[discord-roles] syncDiscordRoles failed (non-fatal)", userId, e);
  }
}
