/**
 * Pure planning logic for keeping the Discord support bridge's categories
 * from filling up. No DB, no network, no `server-only`: everything here takes
 * plain data so test/discord-capacity.test.ts can drive it directly. The
 * runtime half (Discord REST calls, settings) lives in
 * lib/discord-category-pool.ts.
 *
 * WHY THIS EXISTS (incident 2026-10-04 .. 10-07, "no Discord notifications").
 * Discord caps a category at 50 child channels and a guild at 500 channels.
 * The bridge creates one channel per ticket and one per live chat, and on close
 * MOVES it into one "Archived" category instead of deleting it. Archived hit
 * 50 on 2026-10-04, so every later archive move failed (400, parent_id), so
 * closed channels stayed in "Support Tickets" / "Live Chat", which then also
 * hit 50 (tickets 2026-10-04 06:58 UTC, live chat 2026-10-06 18:34 UTC). From
 * then on every createGuildTextChannel call failed with
 * `50035 Invalid Form Body { parent_id: CHANNEL_PARENT_MAX_CHANNELS }`, the
 * bridge's best-effort wrapper swallowed it, and nothing reached Discord.
 */

export const DISCORD_MAX_CHANNELS_PER_CATEGORY = 50;
export const DISCORD_MAX_GUILD_CHANNELS = 500;
/** Never plan to use the last few guild slots: leave room for staff to add channels by hand. */
export const GUILD_CHANNEL_HEADROOM = 15;

/** VIEW_CHANNEL bit, duplicated here (lib/discord.ts is server-only). */
const VIEW_CHANNEL = 1024n;

export type BridgePool = "tickets" | "livechat" | "archived";

export type GuildChannelLite = {
  id: string;
  name: string;
  type: number;
  parent_id: string | null;
  position?: number;
  permission_overwrites?: Array<{ id: string; type: number; allow: string; deny: string }>;
};

export type Overwrite = { id: string; type: 0 | 1; allow: string; deny: string };

/** Setting keys for each pool: the original category plus the comma list of overflow categories the bridge created. */
export const POOL_SETTING_KEYS: Record<BridgePool, { primary: string; overflow: string }> = {
  tickets: { primary: "discord_category_tickets_id", overflow: "discord_category_tickets_overflow_ids" },
  livechat: { primary: "discord_category_livechat_id", overflow: "discord_category_livechat_overflow_ids" },
  archived: { primary: "discord_category_archived_id", overflow: "discord_category_archived_overflow_ids" },
};

export function parseIdList(raw: string | null | undefined): string[] {
  return (raw ?? "")
    .split(/[\s,]+/)
    .map((s) => s.trim())
    .filter((s) => /^\d{5,25}$/.test(s));
}

export function formatIdList(ids: string[]): string {
  return [...new Set(ids)].join(",");
}

/**
 * Did Discord reject a channel create/move because the target category is
 * full? Discord answers 400 / code 50035 with an `errors.parent_id` entry
 * (inner code CHANNEL_PARENT_MAX_CHANNELS). Any parent_id form error is
 * treated as "full" since the bridge only ever passes category ids it read
 * from its own settings.
 */
export function isCategoryFullError(status: number | undefined, json: unknown): boolean {
  if (status !== 400 || !json || typeof json !== "object") return false;
  const j = json as { code?: unknown; errors?: { parent_id?: unknown } };
  if (j.code !== 50035) return false;
  return Boolean(j.errors && typeof j.errors === "object" && j.errors.parent_id);
}

/** 30013 = "Maximum number of guild channels reached (500)". */
export function isGuildFullError(status: number | undefined, json: unknown): boolean {
  if (status !== 400 || !json || typeof json !== "object") return false;
  return (json as { code?: unknown }).code === 30013;
}

/** Discord snowflakes encode creation time; compare as BigInt (they exceed 2^53). */
export function compareSnowflakes(a: string, b: string): number {
  const x = BigInt(a);
  const y = BigInt(b);
  return x < y ? -1 : x > y ? 1 : 0;
}

export function countChildren(channels: GuildChannelLite[], categoryId: string): number {
  return channels.filter((c) => c.parent_id === categoryId).length;
}

/**
 * Pick the category in a pool that still has room. `poolIds` is ordered:
 * primary first, then overflow categories in creation order. Ids that no
 * longer exist in the guild (deleted by hand) are skipped. Returns
 * `create-overflow` when every existing category is full and the guild still
 * has room for a new category plus at least one channel; `guild-full` when it
 * does not.
 */
export function planCategoryPlacement(args: {
  poolIds: string[];
  channels: GuildChannelLite[];
  maxPerCategory?: number;
  maxCategories?: number;
}):
  | { action: "use"; categoryId: string; free: number }
  | { action: "create-overflow"; existing: string[] }
  | { action: "pool-full"; existing: string[] }
  | { action: "guild-full"; existing: string[] } {
  const max = args.maxPerCategory ?? DISCORD_MAX_CHANNELS_PER_CATEGORY;
  const live = args.poolIds.filter((id) => args.channels.some((c) => c.id === id && c.type === 4));
  for (const id of live) {
    const n = countChildren(args.channels, id);
    if (n < max) return { action: "use", categoryId: id, free: max - n };
  }
  if (args.maxCategories !== undefined && live.length >= args.maxCategories) return { action: "pool-full", existing: live };
  // A new category needs 1 slot and is only useful with at least 1 more for the channel itself.
  if (args.channels.length + 2 > DISCORD_MAX_GUILD_CHANNELS - GUILD_CHANNEL_HEADROOM) return { action: "guild-full", existing: live };
  return { action: "create-overflow", existing: live };
}

/** "🎫 Support Tickets" -> "🎫 Support Tickets · 2". Strips an earlier " · N" suffix first. */
export function overflowCategoryName(primaryName: string, index: number): string {
  const base = primaryName.replace(/\s+·\s+\d+$/, "").trim() || "Overflow";
  return `${base} · ${index}`.slice(0, 100);
}

/**
 * Permission overwrites for a new overflow category: copy the primary
 * category's overwrites (staff-role allows etc.) and GUARANTEE an explicit
 * @everyone VIEW_CHANNEL deny (role id == guild id) with no @everyone VIEW
 * allow — the 2026-09-05 ticket-leak lesson: a private category must never
 * rely on anything else to hide it. Member-specific (type 1) overwrites are
 * dropped: they belonged to one customer's channel, not the category.
 */
export function buildOverflowOverwrites(
  primaryOverwrites: Array<{ id: string; type: number; allow: string; deny: string }> | undefined,
  guildId: string,
): Overwrite[] {
  const out: Overwrite[] = [];
  let sawEveryone = false;
  for (const o of primaryOverwrites ?? []) {
    if (o.type !== 0) continue;
    if (o.id === guildId) {
      sawEveryone = true;
      const allow = BigInt(o.allow || "0") & ~VIEW_CHANNEL;
      const deny = BigInt(o.deny || "0") | VIEW_CHANNEL;
      out.push({ id: guildId, type: 0, allow: allow.toString(), deny: deny.toString() });
    } else {
      out.push({ id: o.id, type: 0, allow: o.allow || "0", deny: o.deny || "0" });
    }
  }
  if (!sawEveryone) out.unshift({ id: guildId, type: 0, allow: "0", deny: VIEW_CHANNEL.toString() });
  return out;
}

/**
 * Archive eviction: when every archive category is full and no new one may be
 * created, delete the OLDEST archived channels to make room. Only channels
 * the bridge itself owns (`ownedIds` = ids stored on a CLOSED Ticket or
 * ChatConversation, so their full transcript stays in Nxeon) are ever chosen;
 * anything a human put in the archive by hand is left alone.
 */
export function planArchiveEviction(args: {
  archivedChannels: GuildChannelLite[];
  ownedIds: Set<string>;
  needed: number;
}): string[] {
  if (args.needed <= 0) return [];
  return args.archivedChannels
    .filter((c) => c.type === 0 && args.ownedIds.has(c.id))
    .sort((a, b) => compareSnowflakes(a.id, b.id))
    .slice(0, args.needed)
    .map((c) => c.id);
}

/**
 * Channels sitting in a LIVE pool (tickets / live chat) whose ticket or chat
 * is already CLOSED — left behind because the archive move failed while the
 * archive was full. Archiving them is what frees the live categories.
 */
export function planStaleLiveChannels(args: { liveChannels: GuildChannelLite[]; closedIds: Set<string> }): string[] {
  return args.liveChannels.filter((c) => c.type === 0 && args.closedIds.has(c.id)).map((c) => c.id);
}

/** Render a Discord error body in full (console.error prints nested arrays as `[Array]`, which hid this incident's real cause). */
export function describeDiscordError(status: number | undefined, json: unknown): string {
  let body: string;
  try {
    body = typeof json === "string" ? json : JSON.stringify(json);
  } catch {
    body = String(json);
  }
  return `${status ?? "no-response"} ${body ?? ""}`.slice(0, 600);
}

