cd /tank/nxeon-wt-discord && python3 - <<'EOF'
p='lib/discord.ts'; s=open(p).read()
old_start=s.index('export async function createGuildTextChannel(')
old_end=s.index('/** A button (type 2) inside a single action row')
new='''export async function createGuildTextChannel(
  name: string,
  topic?: string,
  parentId?: string,
  permissionOverwrites?: PermissionOverwrite[],
): Promise<string | null> {
  const r = await createGuildTextChannelDetailed(name, topic, parentId, permissionOverwrites);
  return "id" in r ? r.id : null;
}

/**
 * Same as createGuildTextChannel but tells the caller WHY a create failed, so
 * lib/discord-category-pool.ts can react to a full category (Discord caps a
 * category at 50 channels — the 2026-10-04 notification outage) instead of
 * silently dropping the mirror.
 */
export async function createGuildTextChannelDetailed(
  name: string,
  topic?: string,
  parentId?: string,
  permissionOverwrites?: PermissionOverwrite[],
): Promise<{ id: string } | { error: string; status?: number; categoryFull: boolean; guildFull: boolean }> {
  const guildId = await discordGuildId();
  if (!guildId) {
    console.error("[discord] no guild id configured — cannot create channel");
    return { error: "no guild id configured", categoryFull: false, guildFull: false };
  }
  // Discord channel names: lowercase, hyphens, max 100 chars, no spaces.
  const safeName = name
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 90) || "ticket";

