} from "./discord-capacity";

/**
 * Runtime half of the category-capacity fix (pure logic + the incident write-up
 * are in lib/discord-capacity.ts). Every ticket/live-chat channel the bridge
 * creates, and every archive move, goes through here so a full category grows
 * an overflow category ("🎫 Support Tickets · 2") instead of failing, and a full
 * archive evicts its oldest bridge-owned channels (their transcript lives in
 * Nxeon) instead of blocking every archive move.
 *
 * Same best-effort discipline as lib/discord-bridge.ts: callers already gate on
 * discordEnabled() and wrap in try/catch; nothing here may throw into a
 * ticket/chat write path.
 */

const DEFAULT_POOL_NAMES: Record<BridgePool, string> = {
  tickets: "🎫 Support Tickets",
  livechat: "💬 Live Chat",
  archived: "🗄️ Archived",
};

/** One in-flight overflow creation per pool per process, so two simultaneous tickets don't both create "· 2". */
const poolLocks = new Map<BridgePool, Promise<unknown>>();
async function withPoolLock<T>(pool: BridgePool, fn: () => Promise<T>): Promise<T> {
  const prev = poolLocks.get(pool) ?? Promise.resolve();
  const next = prev.catch(() => undefined).then(fn);
  poolLocks.set(pool, next);
  try {
    return await next;
  } finally {
    if (poolLocks.get(pool) === next) poolLocks.delete(pool);
  }
}

export async function poolCategoryIds(pool: BridgePool): Promise<string[]> {
  const keys = POOL_SETTING_KEYS[pool];
  const primary = (await getSetting(keys.primary, "")).trim();
  const overflow = parseIdList(await getSetting(keys.overflow, ""));
  return [primary, ...overflow].filter(Boolean);
}

async function maxCategoriesFor(pool: BridgePool): Promise<number | undefined> {
  if (pool !== "archived") return undefined; // live pools grow until the guild cap
  const n = await getSettingInt("discord_archive_max_categories", 3);
  return Math.max(1, Math.min(10, n));
}

/** Create the next overflow category for a pool, copying the primary's staff overwrites + a guaranteed @everyone deny. */
async function createOverflowCategory(pool: BridgePool, channels: GuildChannelLite[], existing: string[]): Promise<string | null> {
  const guildId = await discordGuildId();
  if (!guildId) return null;
  const primary = channels.find((c) => c.id === existing[0] && c.type === 4);
  const name = overflowCategoryName(primary?.name ?? DEFAULT_POOL_NAMES[pool], existing.length + 1);
  const id = await createGuildCategory(name, buildOverflowOverwrites(primary?.permission_overwrites, guildId));
  if (!id) return null;
  const key = POOL_SETTING_KEYS[pool].overflow;
  const current = parseIdList(await getSetting(key, ""));
  await setSetting(key, formatIdList([...current, id]));
  console.log(`[discord-pool] created overflow category ${name} (${id}) for ${pool}`);
  return id;
}

/**
 * Evict the oldest bridge-owned archived channels (CLOSED tickets/chats only)
 * and clear their discordThreadId, so a later reopen recreates a channel rather
 * than posting into a deleted one. Returns how many were deleted.
 */
async function evictArchived(channels: GuildChannelLite[], archiveIds: string[], needed: number): Promise<number> {
  if (!(await getSettingBool("discord_archive_evict_when_full", true))) return 0;
  const archivedChannels = channels.filter((c) => c.parent_id && archiveIds.includes(c.parent_id));
  const ids = archivedChannels.map((c) => c.id);
  const [tickets, chats] = await Promise.all([
    db.ticket.findMany({ where: { discordThreadId: { in: ids }, status: "CLOSED" } as any, select: { id: true, discordThreadId: true } as any }),
    db.chatConversation.findMany({ where: { discordThreadId: { in: ids }, status: "CLOSED" } as any, select: { id: true, discordThreadId: true } as any }),
  ]);
  const owned = new Set<string>([...tickets, ...chats].map((r: any) => r.discordThreadId as string));
  const victims = planArchiveEviction({ archivedChannels, ownedIds: owned, needed });
  let deleted = 0;
  for (const channelId of victims) {
    if (!(await deleteChannel(channelId))) continue;
    deleted++;
    await db.ticket.updateMany({ where: { discordThreadId: channelId } as any, data: { discordThreadId: null } as any });
    await db.chatConversation.updateMany({ where: { discordThreadId: channelId } as any, data: { discordThreadId: null } as any });
    const i = channels.findIndex((c) => c.id === channelId);
    if (i >= 0) channels.splice(i, 1);
  }
  if (deleted) console.log(`[discord-pool] evicted ${deleted} oldest archived channel(s) to make room`);
  return deleted;
}

/**
 * The category in `pool` that has room for one more channel, creating an
 * overflow category (or, for the archive, evicting the oldest archived
 * channel) when needed. `channels` may be passed in to save a GET and is
 * mutated to reflect what this call changed. Returns null only when no room
 * can be made.
 */
export async function categoryWithRoom(pool: BridgePool, channels?: GuildChannelLite[]): Promise<string | null> {
  return withPoolLock(pool, async () => {
    const list = channels ?? (await listGuildChannels());
    if (!list) return null;
    const ids = await poolCategoryIds(pool);
    const plan = planCategoryPlacement({ poolIds: ids, channels: list, maxCategories: await maxCategoriesFor(pool) });
    if (plan.action === "use") return plan.categoryId;
    if (plan.action === "create-overflow") {
      const id = await createOverflowCategory(pool, list, plan.existing);
      if (id) list.push({ id, name: "", type: 4, parent_id: null });
      return id;
    }
    if (pool === "archived" && plan.existing.length) {
      if ((await evictArchived(list, plan.existing, 1)) > 0) {
        const again = planCategoryPlacement({ poolIds: plan.existing, channels: list });
        if (again.action === "use") return again.categoryId;
      }
    }
    return null;
  });
}

export type BridgeChannelResult = { id: string } | { error: string };

/**
 * Create a ticket/live-chat channel in the first category of its pool that has
 * room. If Discord still answers "category full" (a race with a human or
 * another process), re-plan once with a fresh channel list.
 */
export async function createBridgeChannel(pool: "tickets" | "livechat", name: string, topic: string): Promise<BridgeChannelResult> {
  let lastError = "no category with room";
  for (let attempt = 0; attempt < 2; attempt++) {
    const parentId = await categoryWithRoom(pool);
    if (!parentId) break;
    const r = await createGuildTextChannelDetailed(name, topic, parentId);
    if ("id" in r) return r;
    lastError = r.error;
    if (!r.categoryFull) break;
  }
  await logError("discord-bridge", new Error(`could not create a ${pool} channel: ${lastError}`), { pool });
  return { error: lastError };
}

/** Move a channel into its live pool (reopen) or the archive pool (close). */
export async function moveBridgeChannel(pool: BridgePool, channelId: string, channels?: GuildChannelLite[]): Promise<boolean> {
  for (let attempt = 0; attempt < 2; attempt++) {
    const target = await categoryWithRoom(pool, attempt === 0 ? channels : undefined);
    if (!target) break;
    const r = await moveChannelToCategoryDetailed(channelId, target);
    if (r.ok) {
      if (channels) {
        const c = channels.find((x) => x.id === channelId);
        if (c) c.parent_id = target;
      }
      return true;
    }
    if (!r.categoryFull) return false;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Fallback: the staff #support-queue channel
// ---------------------------------------------------------------------------

/**
 * The staff-only channel that gets a one-line notice when a ticket/chat
 * channel can't be created at all, so a full guild never means "silently no
 * notification" again. Uses Setting discord_channel_support_queue_id, else a
 * text channel named "support-queue" in the Staff HQ category — and in both
 * cases ONLY if its category carries an explicit @everyone VIEW_CHANNEL deny
 * (never post ticket subjects into a channel that might be public).
 */
export async function supportQueueChannelId(channels?: GuildChannelLite[]): Promise<string | null> {
  const list = channels ?? (await listGuildChannels());
  const guildId = await discordGuildId();
  if (!list || !guildId) return null;
  const configured = (await getSetting("discord_channel_support_queue_id", "")).trim();
  const staffCat = (await getSetting("discord_category_staff_id", "")).trim();
  const candidate = configured
    ? list.find((c) => c.id === configured)
    : list.find((c) => c.type === 0 && c.name === "support-queue" && c.parent_id === staffCat);
  if (!candidate) return null;
  if (!isPrivateToStaff(candidate, list, guildId)) {
    console.error("[discord-pool] support-queue channel is not private (no @everyone deny) — not posting there", candidate.id);
    return null;
  }
  return candidate.id;
}

/** True when the channel itself or (if it has no @everyone overwrite) its parent category denies @everyone VIEW_CHANNEL. */
export function isPrivateToStaff(channel: GuildChannelLite, channels: GuildChannelLite[], guildId: string): boolean {
  const denies = (c: GuildChannelLite | undefined) => {
    const o = c?.permission_overwrites?.find((x) => x.id === guildId && x.type === 0);
    if (!o) return undefined;
    return (BigInt(o.deny || "0") & 1024n) === 1024n && (BigInt(o.allow || "0") & 1024n) === 0n;
  };
  const own = denies(channel);
  if (own !== undefined) return own;
  return denies(channels.find((c) => c.id === channel.parent_id)) === true;
}

const fallbackNotified = new Set<string>();

/** Post a short notice to #support-queue, at most once per ticket/chat per process. Never includes customer email. */
export async function notifySupportQueueFallback(key: string, content: string): Promise<boolean> {
  if (fallbackNotified.has(key)) return false;
  const channelId = await supportQueueChannelId();
  if (!channelId) return false;
  const ok = await postChannelMessage(channelId, content);
  if (ok) {
    fallbackNotified.add(key);
    if (fallbackNotified.size > 5000) fallbackNotified.clear();
  }
  return ok;
}

// ---------------------------------------------------------------------------
// Reconcile sweep (worker) — also the one-shot remediation after deploy
// ---------------------------------------------------------------------------

export type ReconcileReport = {
  dryRun: boolean;
  guildChannels: number;
  pools: Record<BridgePool, Array<{ id: string; name: string; children: number }>>;
  staleLive: { tickets: number; livechat: number };
  archived: number;
  archiveFailed: number;
  backfillCandidates: string[];
  backfilled: number;
  notes: string[];
};

/**
 * Archive every channel left in the live ticket/chat pools whose item is
 * already CLOSED (stuck there while the archive was full), then re-mirror up
 * to `backfillLimit` recent open tickets that never got a channel (created in
 * the last `backfillDays`). `dryRun` makes ZERO Discord writes and ZERO DB
 * writes: it only GETs the guild channel list and reads the DB, and reports
 * what it would do. `maxMoves` caps Discord writes per run (rate limits).
 */
export async function reconcileDiscordBridge(opts: {
  dryRun: boolean;
  maxMoves?: number;
  backfillLimit?: number;
  backfillDays?: number;
}): Promise<ReconcileReport | null> {
  const channels = await listGuildChannels();
  if (!channels) return null;
  const maxMoves = opts.maxMoves ?? 25;
  const report: ReconcileReport = {
    dryRun: opts.dryRun,
    guildChannels: channels.length,
    pools: { tickets: [], livechat: [], archived: [] },
    staleLive: { tickets: 0, livechat: 0 },
    archived: 0,
    archiveFailed: 0,
    backfillCandidates: [],
    backfilled: 0,
    notes: [],
  };
  for (const pool of ["tickets", "livechat", "archived"] as BridgePool[]) {
    for (const id of await poolCategoryIds(pool)) {
      const c = channels.find((x) => x.id === id);
      report.pools[pool].push({ id, name: c?.name ?? "(missing)", children: countChildren(channels, id) });
    }
  }

  let moves = 0;
  for (const pool of ["tickets", "livechat"] as const) {
    const poolIds = await poolCategoryIds(pool);
    const live = channels.filter((c) => c.parent_id && poolIds.includes(c.parent_id));
    const ids = live.map((c) => c.id);
    const rows =
      pool === "tickets"
        ? await db.ticket.findMany({ where: { discordThreadId: { in: ids }, status: "CLOSED" } as any, select: { discordThreadId: true } as any })
        : await db.chatConversation.findMany({ where: { discordThreadId: { in: ids }, status: "CLOSED" } as any, select: { discordThreadId: true } as any });
    const stale = planStaleLiveChannels({ liveChannels: live, closedIds: new Set(rows.map((r: any) => r.discordThreadId as string)) });
    report.staleLive[pool] = stale.length;
    if (opts.dryRun) continue;
    for (const channelId of stale) {
      if (moves >= maxMoves) break;
      moves++;
      if (await moveBridgeChannel("archived", channelId, channels)) report.archived++;
      else report.archiveFailed++;
    }
  }

  const backfillLimit = opts.backfillLimit ?? 10;
  const since = new Date(Date.now() - (opts.backfillDays ?? 7) * 24 * 3600 * 1000);
  const unmirrored = await db.ticket.findMany({
    where: { discordThreadId: null, status: { not: "CLOSED" }, createdAt: { gte: since } } as any,
    orderBy: { createdAt: "asc" },
    take: backfillLimit,
    select: { id: true },
  });
  report.backfillCandidates = unmirrored.map((t) => t.id);
  if (!opts.dryRun && unmirrored.length) {
    const { mirrorNewTicketToDiscord } = await import("./discord-bridge");
    for (const t of unmirrored) {
      await mirrorNewTicketToDiscord(t.id);
      const after = await db.ticket.findUnique({ where: { id: t.id }, select: { discordThreadId: true } as any });
      if ((after as any)?.discordThreadId) report.backfilled++;
    }
  }
  if (opts.dryRun) {
    const archivePlan = planCategoryPlacement({
      poolIds: await poolCategoryIds("archived"),
      channels,
      maxCategories: await maxCategoriesFor("archived"),
    });
    report.notes.push(`archive pool next action: ${archivePlan.action}`);
  }
  return report;
}

/** Worker sweep entry point. Gated on discord_enabled + discord_bridge_reconcile_enabled (default on). */
export async function discordBridgeReconcileSweep(): Promise<void> {
  try {
    if (!(await getSettingBool("discord_enabled", false))) return;
    if (!(await getSettingBool("discord_bridge_reconcile_enabled", true))) return;
    const r = await reconcileDiscordBridge({ dryRun: false });
    if (r && (r.archived || r.archiveFailed || r.backfilled)) {
      console.log(`[discord-pool] reconcile: archived ${r.archived}, failed ${r.archiveFailed}, backfilled ${r.backfilled}/${r.backfillCandidates.length}`);
    }
  } catch (e) {
    console.error("[discord-pool] reconcile sweep failed (non-fatal)", e);
  }
}

