/**
 * One-shot remediation / inspection for the Discord support bridge's category
 * capacity (2026-10-04 outage: Support Tickets, Live Chat and Archived each hit
 * Discord's 50-channels-per-category cap, so no ticket/chat reached Discord).
 *
 *   npx tsx scripts/discord-bridge-reconcile.ts            # DRY RUN (default): GETs + DB reads only
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/discord-bridge-reconcile.ts --apply
 *
 * --apply archives channels of CLOSED tickets/chats still sitting in the live
 * categories (creating "· 2" overflow categories as needed, and evicting the
 * oldest archived bridge channels once discord_archive_max_categories is
 * reached), then mirrors up to 10 open tickets from the last 7 days that never
 * got a channel. It is the same code the web process runs on its own every 15
 * minutes after deploy (lib/discord-category-pool.ts), so running it by hand
 * is optional — it just does the catch-up immediately. Requires owner sign-off:
 * it writes to the live Discord guild.
 *
 * Needs DATABASE_URL and AUTH_SECRET (to decrypt the bot token) in the
 * environment. Never prints the token.
 */
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

// Same idempotent `server-only` shim the test suite uses (lib/discord.ts imports it).
const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
if (!existsSync(join(shimDir, "index.js"))) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(join(shimDir, "index.js"), "module.exports = {};\n");
  writeFileSync(join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js"}\n');
}

async function main() {
  const apply = process.argv.includes("--apply");
  if (apply) {
    const { assertDbTarget } = await import("./db-target-guard");
    assertDbTarget("discord-bridge-reconcile");
  }
  const { reconcileDiscordBridge } = await import("../lib/discord-category-pool");
  const report = await reconcileDiscordBridge({ dryRun: !apply, maxMoves: apply ? 200 : 0 });
  if (!report) {
    console.error("Could not read the guild channel list (discord not configured, or the bot token/guild id is wrong).");
    process.exit(1);
  }
  console.log(JSON.stringify(report, null, 2));
  process.exit(0);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

