import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  DISCORD_MAX_CHANNELS_PER_CATEGORY,
  buildOverflowOverwrites,
  compareSnowflakes,
  describeDiscordError,
  formatIdList,
  isCategoryFullError,
  isGuildFullError,
  overflowCategoryName,
  parseIdList,
  planArchiveEviction,
  planCategoryPlacement,
  planStaleLiveChannels,
  type GuildChannelLite,
} from "../lib/discord-capacity.ts";

/**
 * Regression suite for the 2026-10-04..07 "no Discord notifications" outage:
 * the Support Tickets, Live Chat and Archived categories each reached Discord's
 * 50-channels-per-category cap, every channel create/move then failed with
 * 50035 parent_id, and the bridge silently dropped every mirror.
 */

const GUILD = "1543448442649706679";
const TICKETS = "1543461565708107926";
const LIVECHAT = "1543461567172059248";
const ARCHIVED = "1545537609055608852";

let seq = 1556000000000000000n;
const nextId = () => (seq++).toString();

function category(id: string, name: string, overwrites: GuildChannelLite["permission_overwrites"] = []): GuildChannelLite {
  return { id, name, type: 4, parent_id: null, permission_overwrites: overwrites };
}
function children(parent: string, n: number, prefix = "ticket"): GuildChannelLite[] {
  return Array.from({ length: n }, (_, i) => ({ id: nextId(), name: `${prefix}-${i}`, type: 0, parent_id: parent }));
}

/** Shape of the live guild on 2026-10-07 (read-only GET): 187 channels, three bridge categories at 50/50. */
function incidentGuild(): GuildChannelLite[] {
  const staffOverwrites = [
    { id: GUILD, type: 0, allow: "0", deny: "1024" },
    { id: "1545534877481574480", type: 0, allow: "1024", deny: "0" },
    { id: "1545534885433839707", type: 0, allow: "1024", deny: "0" },
  ];
  const list: GuildChannelLite[] = [
    category(TICKETS, "🎫 Support Tickets", staffOverwrites),
    category(LIVECHAT, "💬 Live Chat", staffOverwrites),
    category(ARCHIVED, "🗄️ Archived", staffOverwrites),
    ...children(TICKETS, 50),
    ...children(LIVECHAT, 50, "chat"),
    ...children(ARCHIVED, 50),
  ];
  while (list.length < 187) list.push({ id: nextId(), name: "other", type: 0, parent_id: null });
  return list;
}

// The exact error body Discord returned 132 times in prod journald (2026-10-04..07).
const FULL_CATEGORY_ERROR = {
  message: "Invalid Form Body",
  code: 50035,
  errors: { parent_id: { _errors: [{ code: "CHANNEL_PARENT_MAX_CHANNELS", message: "Maximum number of channels in category reached (50)" }] } },
};

test("the prod error body is recognised as 'category full'", () => {
  assert.equal(isCategoryFullError(400, FULL_CATEGORY_ERROR), true);
  assert.equal(isCategoryFullError(400, { code: 50035, errors: { name: { _errors: [] } } }), false, "other form errors are not 'full'");
  assert.equal(isCategoryFullError(403, FULL_CATEGORY_ERROR), false);
  assert.equal(isCategoryFullError(400, null), false);
  assert.equal(isGuildFullError(400, { code: 30013, message: "Maximum number of guild channels reached (500)" }), true);
  assert.equal(isGuildFullError(400, FULL_CATEGORY_ERROR), false);
});

test("REGRESSION: a full ticket category plans an overflow category instead of failing", () => {
  const guild = incidentGuild();
  const plan = planCategoryPlacement({ poolIds: [TICKETS], channels: guild });
  assert.equal(plan.action, "create-overflow");
  assert.deepEqual((plan as { existing: string[] }).existing, [TICKETS]);
});

test("an overflow category with room is used once it exists", () => {
  const guild = incidentGuild();
  const overflow = nextId();
  guild.push(category(overflow, "🎫 Support Tickets · 2"));
  const plan = planCategoryPlacement({ poolIds: [TICKETS, overflow], channels: guild });
  assert.deepEqual(plan, { action: "use", categoryId: overflow, free: DISCORD_MAX_CHANNELS_PER_CATEGORY });
});

test("the primary is reused as soon as it has room again (after stale channels are archived)", () => {
  const guild = incidentGuild();
  const overflow = nextId();
  guild.push(category(overflow, "🎫 Support Tickets · 2"));
  const idx = guild.findIndex((c) => c.parent_id === TICKETS);
  guild.splice(idx, 1);
  const plan = planCategoryPlacement({ poolIds: [TICKETS, overflow], channels: guild });
  assert.equal(plan.action, "use");
  assert.equal((plan as { categoryId: string }).categoryId, TICKETS);
});

test("pool ids that no longer exist in the guild (deleted by hand) are skipped", () => {
  const guild = incidentGuild();
  const plan = planCategoryPlacement({ poolIds: ["999999999999999999", LIVECHAT], channels: guild });
  assert.equal(plan.action, "create-overflow");
  assert.deepEqual((plan as { existing: string[] }).existing, [LIVECHAT]);
});

test("the archive pool stops growing at maxCategories (then eviction takes over)", () => {
  const guild = incidentGuild();
  assert.equal(planCategoryPlacement({ poolIds: [ARCHIVED], channels: guild, maxCategories: 1 }).action, "pool-full");
  assert.equal(planCategoryPlacement({ poolIds: [ARCHIVED], channels: guild, maxCategories: 3 }).action, "create-overflow");
});

test("near the 500-channel guild cap no new category is planned", () => {
  const guild = incidentGuild();
  while (guild.length < 485) guild.push({ id: nextId(), name: "x", type: 0, parent_id: null });
  assert.equal(planCategoryPlacement({ poolIds: [TICKETS], channels: guild }).action, "guild-full");
});

test("overflow category names", () => {
  assert.equal(overflowCategoryName("🎫 Support Tickets", 2), "🎫 Support Tickets · 2");
  assert.equal(overflowCategoryName("🎫 Support Tickets · 2", 3), "🎫 Support Tickets · 3");
  assert.equal(overflowCategoryName("", 2), "Overflow · 2");
});

test("LEAK GUARD: overflow categories always deny @everyone VIEW_CHANNEL", () => {
  // primary has an explicit deny -> kept, staff allows copied, member overwrites dropped
  const copied = buildOverflowOverwrites(
    [
      { id: GUILD, type: 0, allow: "0", deny: "1024" },
      { id: "111", type: 0, allow: "1024", deny: "0" },
      { id: "222", type: 1, allow: "1024", deny: "0" },
    ],
    GUILD,
  );
  assert.deepEqual(copied, [
    { id: GUILD, type: 0, allow: "0", deny: "1024" },
    { id: "111", type: 0, allow: "1024", deny: "0" },
  ]);
  // primary missing the deny (the 2026-09-05 bug) -> deny is added anyway
  const added = buildOverflowOverwrites([{ id: "111", type: 0, allow: "1024", deny: "0" }], GUILD);
  assert.deepEqual(added[0], { id: GUILD, type: 0, allow: "0", deny: "1024" });
  // primary that ALLOWS @everyone view -> flipped to deny, other bits kept
  const flipped = buildOverflowOverwrites([{ id: GUILD, type: 0, allow: String(1024 | 2048), deny: "0" }], GUILD);
  assert.deepEqual(flipped[0], { id: GUILD, type: 0, allow: "2048", deny: "1024" });
  // no primary at all
