  assert.deepEqual(planArchiveEviction({ archivedChannels: [a, b], ownedIds: owned, needed: 0 }), []);
  assert.deepEqual(planArchiveEviction({ archivedChannels: [human], ownedIds: owned, needed: 1 }), [], "never evicts a channel the bridge doesn't own");
});

test("stale live channels = live-pool channels whose ticket/chat is CLOSED", () => {
  const live = children(TICKETS, 4);
  const closed = new Set([live[0].id, live[2].id, "not-in-pool"]);
