  assert.equal(compareSnowflakes("1556000000000000001", "1556000000000000002"), -1);
  assert.equal(compareSnowflakes("1556000000000000002", "1556000000000000002"), 0);
});

test("id lists round-trip and drop junk", () => {
  assert.deepEqual(parseIdList(" 1556000000000000001, ,abc,1556000000000000002 "), ["1556000000000000001", "1556000000000000002"]);
  assert.equal(formatIdList(["1", "1", "2"]), "1,2");
