import { NextResponse } from "next/server";
import {
  discordPublicKey,
  verifyDiscordSignature,
  InteractionType,
  replyModalResponse,
  newTicketModalResponse,
  channelMessageResponse,
  ephemeralMessageResponse,
  extractModalText,
  extractModalFields,
  extractInteractionUserId,
} from "@/lib/discord";
import { parseBridgeCustomId, replyModalCustomId, submitDiscordReply } from "@/lib/discord-bridge";
import { buildStatusReply } from "@/lib/discord-status-command";
import { canOpenTicketFromDiscord, createTicketFromDiscord } from "@/lib/discord-support-command";

export const runtime = "nodejs";

/**
export async function POST(req: Request) {
  const rawBody = await req.text();
  const signature = req.headers.get("X-Signature-Ed25519");
  const timestamp = req.headers.get("X-Signature-Timestamp");
  const publicKeyHex = await discordPublicKey();

  if (!publicKeyHex) {
    console.error("[discord-webhook] no discord_public_key configured — rejecting");
    return NextResponse.json({ error: "not configured" }, { status: 401 });
  }

  const valid = verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex });
  if (!valid) {
    return NextResponse.json({ error: "invalid request signature" }, { status: 401 });
  }

  let interaction: Record<string, unknown>;
  try {
    interaction = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: "invalid body" }, { status: 400 });
  }

  const type = interaction.type as number | undefined;

  if (type === InteractionType.PING) {
    return NextResponse.json({ type: 1 });
  }

  if (type === InteractionType.MESSAGE_COMPONENT) {
    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
    if (customId === "welcome_guest") {
      return NextResponse.json(
        ephemeralMessageResponse(
          "No problem — you're all set to look around. You can connect your Nxeon account any time from #welcome or nxeon.cloud/dashboard/settings.",
        ),
      );
    }
    const parsed = parseBridgeCustomId(customId);
    if (!parsed || parsed.action !== "reply") {
      return NextResponse.json(channelMessageResponse("Unrecognized button."));
    }
    return NextResponse.json(replyModalResponse(replyModalCustomId(parsed.kind, parsed.id)));
  }

  if (type === InteractionType.MODAL_SUBMIT) {
    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
    if (customId === "dc_new_ticket_modal") {
      const fields = extractModalFields(interaction);
      const discordUserId = extractInteractionUserId(interaction);
      const ackText = await createTicketFromDiscord(discordUserId, fields.ticket_subject ?? "", fields.ticket_body ?? "");
      return NextResponse.json(ephemeralMessageResponse(ackText));
    }
    const parsed = parseBridgeCustomId(customId);
    if (!parsed || parsed.action !== "reply_modal") {
      return NextResponse.json(channelMessageResponse("Unrecognized submission."));
    }
    const text = extractModalText(interaction);
    const discordUserId = extractInteractionUserId(interaction);
    const ackText = await submitDiscordReply(parsed.kind, parsed.id, text, discordUserId);
    return NextResponse.json(channelMessageResponse(ackText));
  }

  if (type === InteractionType.APPLICATION_COMMAND) {
    const name = (interaction.data as { name?: string } | undefined)?.name;
    if (name === "status") {
      const discordUserId = extractInteractionUserId(interaction);
      const reply = await buildStatusReply(discordUserId);
      return NextResponse.json(ephemeralMessageResponse(reply));
    }
    if (name === "support") {
      const discordUserId = extractInteractionUserId(interaction);
      const gate = await canOpenTicketFromDiscord(discordUserId);
      if (!gate.ok) return NextResponse.json(ephemeralMessageResponse(gate.message));
      return NextResponse.json(newTicketModalResponse());
    }
    return NextResponse.json(ephemeralMessageResponse("Unknown command."));
  }

  return NextResponse.json(channelMessageResponse("This interaction isn't handled."));
}

