import "server-only";
import { db } from "./db";
import { createTicketCore } from "./reply-core";
import { mirrorNewTicketToDiscord } from "./discord-bridge";

const LINK_PROMPT =
  "You haven't linked a Nxeon account yet. Connect one from Settings → Integrations at nxeon.cloud/dashboard/settings, or use the button pinned in #welcome, then try /support again.";

/** Is this Discord user linked to a (non-suspended) Nxeon account? Gates
 *  whether /support opens the new-ticket modal at all. */
export async function canOpenTicketFromDiscord(discordUserId: string | null): Promise<{ ok: true } | { ok: false; message: string }> {
  if (!discordUserId) return { ok: false, message: LINK_PROMPT };
  const user = await db.user.findUnique({ where: { discordUserId } as any, select: { suspended: true } });
  if (!user) return { ok: false, message: LINK_PROMPT };
  if (user.suspended) return { ok: false, message: "This account is suspended." };
  return { ok: true };
}

/**
 * Create a ticket from the /support modal submission. Re-resolves the
 * linked account from the Discord-signed interaction user id (never trusts
 * anything client-supplied beyond that id) — same discipline as
 * lib/discord-bridge.ts's resolveDiscordReplyActor. Reuses createTicketCore
 * (lib/reply-core.ts) so this is byte-identical, in DB terms, to opening a
 * ticket from the dashboard — then mirrors it back to Discord exactly like
 * any other ticket, which is what lands the customer in their own
 * newly-created channel (lib/discord-bridge.ts's grantCustomerAccessAndSummary
 * runs as part of that same mirror).
 */
export async function createTicketFromDiscord(
  discordUserId: string | null,
  subject: string,
  body: string,
): Promise<string> {
  if (!discordUserId) return LINK_PROMPT;
  const user = await db.user.findUnique({ where: { discordUserId } as any, select: { id: true, suspended: true } });
  if (!user) return LINK_PROMPT;
  if (user.suspended) return "This account is suspended.";

  const subjectTrimmed = subject.trim().slice(0, 150);
  const bodyTrimmed = body.trim().slice(0, 4000);
  if (subjectTrimmed.length < 3 || bodyTrimmed.length < 5) {
    return "Subject (3+ characters) and description (5+ characters) are required. Run /support again.";
  }

  const ticket = await createTicketCore({ userId: user.id, subject: subjectTrimmed, body: bodyTrimmed });
  await mirrorNewTicketToDiscord(ticket.ticketId);
  return `🎫 Ticket created: **${ticket.subject}**. Check your ticket channel here in the server, or nxeon.cloud/dashboard/support.`;
}

