/**
 * The target structure for the rebuilt Nxeon Discord server, as DATA. The
 * planner (lib/discord-redo/plan.ts) diffs this against the live guild and
 * produces the operations scripts/discord-redo-apply.ts prints (dry run) or,
 * only with owner approval, applies. See /root/agent-notes/discord-redo/PLAN.md
 * for the reasoning behind every category/role here.
 *
 * Matching rules (so the redo REUSES what exists and keeps every member's
 * roles): a role/category/channel is matched first by the id stored in its
 * `settingKey`, then by current name / `aliases`. Nothing is ever deleted;
 * unmatched old channels are moved into a staff-only "Legacy" category.
 */
import type { PermName } from "./permissions";

export type RoleKey =
  | "owner"
  | "admin"
  | "manager"
  | "moderator"
  | "staff"
  | "support"
  | "bots"
  | "partner"
  | "verified"
  | "vps"
  | "game"
  | "hosting"
  | "ping_announcements"
  | "ping_status"
  | "ping_giveaways"
  | "game_minecraft"
  | "game_valheim"
  | "game_rust"
  | "game_palworld"
  | "game_ark"
  | "game_other";

export type RoleSpec = {
  key: RoleKey;
  name: string;
  color: number;
  hoist: boolean;
  mentionable: boolean;
  /** Guild-level permissions. Members get the @everyone base below + these. */
  permissions: PermName[];
  settingKey?: string;
  aliases?: string[];
};

/** "@everyone" is the guild id; "bot" is the Nxeon Support bot's managed role. */
export type Principal = RoleKey | "@everyone" | "bot";

export type OverwriteSpec = { who: Principal; allow?: PermName[]; deny?: PermName[] };

export type ChannelKind = "text" | "announcement" | "forum" | "voice" | "stage";

export type ChannelSpec = {
  key: string;
  name: string;
  kind: ChannelKind;
  topic?: string;
  /** Seconds. */
  slowmode?: number;
  /** Forum tags. */
  tags?: string[];
  /** Overwrites ON TOP of the category's (Discord does not merge: a channel with its own overwrites stops syncing). */
  overwrites?: OverwriteSpec[];
  settingKey?: string;
  aliases?: string[];
};

export type CategorySpec = {
  key: string;
  name: string;
  overwrites: OverwriteSpec[];
  channels: ChannelSpec[];
  settingKey?: string;
  aliases?: string[];
};

export type ServerSpec = {
  /** Base permissions for @everyone (guild level). Deliberately small. */
  everyone: PermName[];
  roles: RoleSpec[];
  categories: CategorySpec[];
  legacyCategoryName: string;
  /** Guild settings to apply (PATCH /guilds/{id}). */
  guild: {
    verificationLevel: 0 | 1 | 2 | 3 | 4;
    /** 1 = only @mentions. */
    defaultMessageNotifications: 0 | 1;
    /** 2 = scan media from all members. */
    explicitContentFilter: 0 | 1 | 2;
    rulesChannel: string;
    systemChannel: string;
    publicUpdatesChannel: string;
    safetyAlertsChannel: string;
  };
  /** Setting keys whose categories the support bridge owns: never touched, never "legacy". */
  bridgeCategorySettingKeys: string[];
};

// --- permission bundles -----------------------------------------------------

const READ: PermName[] = ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY"];
const CHAT: PermName[] = ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY", "SEND_MESSAGES", "SEND_MESSAGES_IN_THREADS", "ADD_REACTIONS", "EMBED_LINKS", "ATTACH_FILES"];
const NO_POST: PermName[] = ["SEND_MESSAGES", "CREATE_PUBLIC_THREADS", "CREATE_PRIVATE_THREADS", "ADD_REACTIONS"];
const VOICE: PermName[] = ["VIEW_CHANNEL", "CONNECT", "SPEAK", "USE_VAD", "STREAM"];
const STAFF_SEE: OverwriteSpec[] = [
  { who: "@everyone", deny: ["VIEW_CHANNEL"] },
  { who: "staff", allow: CHAT },
  { who: "support", allow: CHAT },
  { who: "moderator", allow: CHAT },
  { who: "manager", allow: CHAT },
  { who: "admin", allow: CHAT },
  { who: "bot", allow: [...CHAT, "MANAGE_THREADS", "CREATE_PRIVATE_THREADS", "MANAGE_CHANNELS"] },
];
const READ_ONLY_PUBLIC: OverwriteSpec[] = [
  { who: "@everyone", allow: READ, deny: NO_POST },
  { who: "staff", allow: ["SEND_MESSAGES", "ADD_REACTIONS"] },
  { who: "bot", allow: ["SEND_MESSAGES", "EMBED_LINKS"] },
];

// --- the spec ---------------------------------------------------------------

export const NXEON_SERVER_SPEC: ServerSpec = {
  everyone: [
    "VIEW_CHANNEL",
    "READ_MESSAGE_HISTORY",
    "SEND_MESSAGES",
    "SEND_MESSAGES_IN_THREADS",
