    // NOT: CREATE_INSTANT_INVITE, MENTION_EVERYONE, CREATE_PRIVATE_THREADS, USE_EXTERNAL_APPS, SEND_POLLS, soundboard
  ],
  roles: [
    // Order = hierarchy, top first. The bot's managed role must sit above every role it assigns.
    { key: "owner", name: "👑 Owner", color: 0xf5b942, hoist: true, mentionable: false, permissions: ["ADMINISTRATOR"], settingKey: "discord_role_owner_id" },
