  aliases?: string[];
};

export type CategorySpec = {
  key: string;
  name: string;
  overwrites: OverwriteSpec[];
  channels: ChannelSpec[];
  settingKey?: string;
  aliases?: string[];
};

export type ServerSpec = {
  /** Base permissions for @everyone (guild level). Deliberately small. */
  everyone: PermName[];
  roles: RoleSpec[];
  categories: CategorySpec[];
  legacyCategoryName: string;
  /** Guild settings to apply (PATCH /guilds/{id}). */
  guild: {
    verificationLevel: 0 | 1 | 2 | 3 | 4;
    /** 1 = only @mentions. */
    defaultMessageNotifications: 0 | 1;
    /** 2 = scan media from all members. */
    explicitContentFilter: 0 | 1 | 2;
    rulesChannel: string;
    systemChannel: string;
    publicUpdatesChannel: string;
    safetyAlertsChannel: string;
  };
  /** Setting keys whose categories the support bridge owns: never touched, never "legacy". */
  bridgeCategorySettingKeys: string[];
};

// --- permission bundles -----------------------------------------------------

const READ: PermName[] = ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY"];
const CHAT: PermName[] = ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY", "SEND_MESSAGES", "SEND_MESSAGES_IN_THREADS", "ADD_REACTIONS", "EMBED_LINKS", "ATTACH_FILES"];
const NO_POST: PermName[] = ["SEND_MESSAGES", "CREATE_PUBLIC_THREADS", "CREATE_PRIVATE_THREADS", "ADD_REACTIONS"];
const VOICE: PermName[] = ["VIEW_CHANNEL", "CONNECT", "SPEAK", "USE_VAD", "STREAM"];
