  { who: "manager", allow: CHAT },
  { who: "admin", allow: CHAT },
  { who: "bot", allow: [...CHAT, "MANAGE_THREADS", "CREATE_PRIVATE_THREADS", "MANAGE_CHANNELS"] },
];
const READ_ONLY_PUBLIC: OverwriteSpec[] = [
  { who: "@everyone", allow: READ, deny: NO_POST },
  { who: "staff", allow: ["SEND_MESSAGES", "ADD_REACTIONS"] },
  { who: "bot", allow: ["SEND_MESSAGES", "EMBED_LINKS"] },
