/**
 * Pure diff planner: target spec (lib/discord-redo/spec.ts) + the live guild
 * (a read-only GET of channels and roles) + current settings -> an ordered list
 * of operations. No network, no DB: scripts/discord-redo-apply.ts prints the
 * plan (dry run, the default) and lib/discord-redo/execute.ts applies it only
 * with explicit owner approval.
 *
 * Invariants (tested in test/discord-redo-plan.test.ts):
 *  - never deletes anything; unmatched old channels move to a staff-only,
 *    read-only Legacy category so their history stays readable by staff;
 *  - never touches the support bridge's ticket / live-chat / archive
 *    categories or anything inside them;
 *  - every private category/channel carries an explicit @everyone VIEW deny;
 *  - no customer, ping or game role is granted a dangerous permission.
 */
import { bitsString, type PermName } from "./permissions";
import type { CategorySpec, ChannelKind, ChannelSpec, OverwriteSpec, Principal, RoleSpec, ServerSpec } from "./spec";

export type LiveChannel = {
  id: string;
  name: string;
  type: number;
  parent_id: string | null;
  position?: number;
  topic?: string | null;
  rate_limit_per_user?: number;
  available_tags?: Array<{ name: string }>;
  permission_overwrites?: Array<{ id: string; type: number; allow: string; deny: string }>;
};

export type LiveRole = {
  id: string;
  name: string;
  permissions: string;
  color: number;
  hoist: boolean;
  mentionable: boolean;
  managed: boolean;
  position: number;
};

export type LiveGuild = { id: string; channels: LiveChannel[]; roles: LiveRole[] };

/** A value that is either a concrete id or a "$ref" resolved at execution time ("$role:verified", "$cat:start", "$ch:rules", "$legacy"). */
export type Ref = string;

export type WireOverwrite = { id: Ref; type: 0 | 1; allow: string; deny: string };

export type Op =
  | { op: "update-everyone"; id: string; permissions: string; from: string }
  | { op: "create-role"; ref: Ref; body: { name: string; color: number; hoist: boolean; mentionable: boolean; permissions: string } }
  | { op: "update-role"; ref: Ref; id: string; changes: string[]; body: Record<string, unknown> }
  | { op: "reorder-roles"; order: Ref[] }
  | { op: "create-category"; ref: Ref; body: { name: string; type: 4; permission_overwrites: WireOverwrite[] } }
  | { op: "create-channel"; ref: Ref; body: Record<string, unknown> & { name: string; type: number; parent_id: Ref } }
  | { op: "update-channel"; ref: Ref; id: string; changes: string[]; body: Record<string, unknown> }
  | { op: "move-to-legacy"; id: string; name: string; reason: string }
  | { op: "post-panel"; channel: Ref; panel: "open_ticket" | "link_account" | "rules" | "welcome" }
  | { op: "update-guild"; body: Record<string, unknown> }
  | { op: "set-setting"; key: string; value: Ref }
  | { op: "note"; text: string };

export const CHANNEL_TYPE_OF: Record<ChannelKind, number> = { text: 0, voice: 2, announcement: 5, stage: 13, forum: 15 };

const LEGACY_REF = "$legacy";

function principalId(who: Principal, guildId: string, botRoleId: string | null): Ref {
  if (who === "@everyone") return guildId;
  if (who === "bot") return botRoleId ?? "$bot";
  return `$role:${who}`;
}

function toWire(list: OverwriteSpec[], guildId: string, botRoleId: string | null): WireOverwrite[] {
  const byId = new Map<string, WireOverwrite>();
  for (const o of list) {
    const id = principalId(o.who, guildId, botRoleId);
    if (id === "$bot") continue; // no bot role known: the bot has Administrator today anyway
    byId.set(id, { id, type: 0, allow: bitsString(o.allow ?? []), deny: bitsString(o.deny ?? []) });
  }
  return [...byId.values()];
}

/** A channel's effective overwrites: its category's, with the channel's own entries replacing per principal. */
export function mergeOverwrites(category: OverwriteSpec[], channel: OverwriteSpec[] | undefined): OverwriteSpec[] {
  if (!channel || channel.length === 0) return category;
  const map = new Map<string, OverwriteSpec>();
  for (const o of category) map.set(o.who, o);
  for (const o of channel) map.set(o.who, o);
  return [...map.values()];
}

function normOverwrites(list: Array<{ id: string; type: number; allow: string; deny: string }> | undefined): string {
  return (list ?? [])
    .filter((o) => !(o.allow === "0" && o.deny === "0"))
    .map((o) => `${o.id}|${o.type}|${o.allow}|${o.deny}`)
    .sort()
    .join(",");
}

function resolveForCompare(list: WireOverwrite[], roleIds: Map<string, string>): Array<{ id: string; type: number; allow: string; deny: string }> | null {
  const out = [];
  for (const o of list) {
    if (o.id.startsWith("$role:")) {
      const id = roleIds.get(o.id.slice(6));
      if (!id) return null; // role is being created in this run: definitely differs
      out.push({ ...o, id });
    } else out.push(o);
  }
  return out;
}

/** Only text<->announcement can be converted in place (Community guilds). */
function convertible(fromType: number, toType: number): boolean {
  if (fromType === toType) return true;
  return (fromType === 0 && toType === 5) || (fromType === 5 && toType === 0);
}

export function planServerRedo(args: {
  spec: ServerSpec;
  guild: LiveGuild;
  settings: Record<string, string>;
  botRoleId: string | null;
}): Op[] {
  const { spec, guild, settings, botRoleId } = args;
  const ops: Op[] = [];
  const used = new Set<string>();
  const roleIds = new Map<string, string>(); // role key -> live id

  // --- @everyone base ---------------------------------------------------------
  const everyone = guild.roles.find((r) => r.id === guild.id);
  const everyoneBits = bitsString(spec.everyone);
  if (everyone && everyone.permissions !== everyoneBits) {
    ops.push({ op: "update-everyone", id: guild.id, permissions: everyoneBits, from: everyone.permissions });
  }

  // --- roles ------------------------------------------------------------------
  const takenRoles = new Set<string>([guild.id]);
  for (const r of spec.roles) {
    const live = matchRole(r, guild.roles, settings, takenRoles);
    const body = { name: r.name, color: r.color, hoist: r.hoist, mentionable: r.mentionable, permissions: bitsString(r.permissions) };
    if (!live) {
      ops.push({ op: "create-role", ref: `$role:${r.key}`, body });
      if (r.settingKey) ops.push({ op: "set-setting", key: r.settingKey, value: `$role:${r.key}` });
      continue;
    }
    takenRoles.add(live.id);
    roleIds.set(r.key, live.id);
    const changes: string[] = [];
    if (live.name !== r.name) changes.push(`name ${JSON.stringify(live.name)} -> ${JSON.stringify(r.name)}`);
    if (live.permissions !== body.permissions) changes.push("permissions");
    if (live.color !== r.color) changes.push("color");
    if (live.hoist !== r.hoist) changes.push("hoist");
    if (live.mentionable !== r.mentionable) changes.push("mentionable");
    if (changes.length) ops.push({ op: "update-role", ref: `$role:${r.key}`, id: live.id, changes, body });
    if (r.settingKey && settings[r.settingKey] !== live.id) ops.push({ op: "set-setting", key: r.settingKey, value: live.id });
  }
  ops.push({ op: "reorder-roles", order: spec.roles.map((r) => `$role:${r.key}`) });
  const strayManaged = guild.roles.filter((r) => r.managed && r.id !== botRoleId);
  for (const r of strayManaged) ops.push({ op: "note", text: `managed role "${r.name}" (another bot/integration) left as is` });
  for (const r of guild.roles.filter((x) => !x.managed && !takenRoles.has(x.id))) {
    ops.push({ op: "note", text: `role "${r.name}" is not in the spec: left untouched (members keep it)` });
  }

  // --- bridge categories are off limits --------------------------------------
  const bridgeCats = new Set<string>();
  for (const key of spec.bridgeCategorySettingKeys) {
    for (const id of (settings[key] ?? "").split(/[\s,]+/).filter(Boolean)) bridgeCats.add(id);
  }
  for (const id of bridgeCats) used.add(id);
  const inBridge = (c: LiveChannel) => bridgeCats.has(c.id) || (c.parent_id !== null && bridgeCats.has(c.parent_id));

  // --- categories + channels ---------------------------------------------------
  const legacyMoves: Array<{ id: string; name: string; reason: string }> = [];
  for (const cat of spec.categories) {
    const catRef = `$cat:${cat.key}`;
    const liveCat = matchChannel(cat, 4, guild.channels, settings, used, inBridge);
    const catWire = toWire(cat.overwrites, guild.id, botRoleId);
    let parentRef: Ref;
    if (!liveCat) {
      ops.push({ op: "create-category", ref: catRef, body: { name: cat.name, type: 4, permission_overwrites: catWire } });
      if (cat.settingKey) ops.push({ op: "set-setting", key: cat.settingKey, value: catRef });
      parentRef = catRef;
    } else {
      used.add(liveCat.id);
      parentRef = liveCat.id;
      const changes: string[] = [];
      const body: Record<string, unknown> = {};
      if (liveCat.name !== cat.name) {
        changes.push(`name ${JSON.stringify(liveCat.name)} -> ${JSON.stringify(cat.name)}`);
        body.name = cat.name;
      }
      const cmp = resolveForCompare(catWire, roleIds);
      if (!cmp || normOverwrites(cmp) !== normOverwrites(liveCat.permission_overwrites)) {
        changes.push("permission_overwrites");
        body.permission_overwrites = catWire;
      }
      if (changes.length) ops.push({ op: "update-channel", ref: catRef, id: liveCat.id, changes, body });
      if (cat.settingKey && settings[cat.settingKey] !== liveCat.id) ops.push({ op: "set-setting", key: cat.settingKey, value: liveCat.id });
    }

    for (const ch of cat.channels) {
      planChannel({ ch, cat, parentRef, guild, settings, used, inBridge, botRoleId, roleIds, ops, legacyMoves });
    }
  }

  // --- everything else -> legacy -------------------------------------------------
  for (const c of guild.channels) {
    if (used.has(c.id) || inBridge(c)) continue;
    if (c.type === 4) continue; // categories handled below
    legacyMoves.push({ id: c.id, name: c.name, reason: "not in the new layout" });
  }
  if (legacyMoves.length) {
    const legacyWire = toWire(
      [
        { who: "@everyone", deny: ["VIEW_CHANNEL"] },
        { who: "staff", allow: ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY"], deny: ["SEND_MESSAGES", "SEND_MESSAGES_IN_THREADS", "CONNECT"] },
        { who: "admin", allow: ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY"] },
        { who: "bot", allow: ["VIEW_CHANNEL", "READ_MESSAGE_HISTORY", "MANAGE_CHANNELS"] },
      ],
      guild.id,
      botRoleId,
    );
    ops.push({ op: "create-category", ref: LEGACY_REF, body: { name: spec.legacyCategoryName, type: 4, permission_overwrites: legacyWire } });
    for (const m of legacyMoves) ops.push({ op: "move-to-legacy", ...m });
  }
  for (const c of guild.channels) {
    if (c.type !== 4 || used.has(c.id) || bridgeCats.has(c.id)) continue;
    ops.push({ op: "note", text: `category "${c.name}" is not in the new layout; once empty it can be deleted by hand (not deleted by this script)` });
  }

  // --- guild settings ------------------------------------------------------------
  const g = spec.guild;
  ops.push({
    op: "update-guild",
    body: {
      verification_level: g.verificationLevel,
      default_message_notifications: g.defaultMessageNotifications,
      explicit_content_filter: g.explicitContentFilter,
      rules_channel_id: chRef(g.rulesChannel),
      system_channel_id: chRef(g.systemChannel),
      public_updates_channel_id: chRef(g.publicUpdatesChannel),
      safety_alerts_channel_id: chRef(g.safetyAlertsChannel),
    },
  });
  ops.push({ op: "note", text: "Owner, in Discord: Server Settings > Safety Setup > require 2FA for moderation; Onboarding questions (games, pings); AutoMod rules (see PLAN.md)." });
  ops.push({ op: "note", text: "Owner, in Discord: Server Settings > Integrations > Nxeon Support: drop Administrator for the explicit list in PLAN.md (after the apply)." });
  return ops;

  function chRef(key: string): Ref {
    return `$ch:${key}`;
  }
}

function planChannel(a: {
  ch: ChannelSpec;
  cat: CategorySpec;
  parentRef: Ref;
  guild: LiveGuild;
  settings: Record<string, string>;
  used: Set<string>;
  inBridge: (c: LiveChannel) => boolean;
  botRoleId: string | null;
  roleIds: Map<string, string>;
  ops: Op[];
  legacyMoves: Array<{ id: string; name: string; reason: string }>;
}) {
  const { ch, cat, parentRef, guild, settings, used, inBridge, botRoleId, roleIds, ops, legacyMoves } = a;
  const ref = `$ch:${ch.key}`;
  const type = CHANNEL_TYPE_OF[ch.kind];
  const wire = toWire(mergeOverwrites(cat.overwrites, ch.overwrites), guild.id, botRoleId);
  const live = matchChannel(ch, null, guild.channels, settings, used, inBridge);
  const createBody = (): Record<string, unknown> & { name: string; type: number; parent_id: Ref } => {
    const body: Record<string, unknown> & { name: string; type: number; parent_id: Ref } = { name: ch.name, type, parent_id: parentRef, permission_overwrites: wire };
    if (ch.topic && (type === 0 || type === 5 || type === 15)) body.topic = ch.topic;
    if (ch.slowmode && (type === 0 || type === 15)) body.rate_limit_per_user = ch.slowmode;
    if (ch.tags && type === 15) body.available_tags = ch.tags.map((name) => ({ name }));
    return body;
  };
  const panelFor = (k: string): "open_ticket" | "link_account" | "rules" | "welcome" | null =>
    k === "open_ticket" ? "open_ticket" : k === "link_account" ? "link_account" : k === "rules" ? "rules" : k === "welcome" ? "welcome" : null;

  if (live && !convertible(live.type, type)) {
    used.add(live.id);
    legacyMoves.push({ id: live.id, name: live.name, reason: `replaced by new ${ch.kind} #${ch.name} (type can't be converted)` });
    ops.push({ op: "create-channel", ref, body: createBody() });
  } else if (!live) {
    ops.push({ op: "create-channel", ref, body: createBody() });
  } else {
    used.add(live.id);
    const changes: string[] = [];
    const body: Record<string, unknown> = {};
    if (live.name !== ch.name) {
      changes.push(`name ${JSON.stringify(live.name)} -> ${JSON.stringify(ch.name)}`);
      body.name = ch.name;
    }
    if (live.type !== type) {
      changes.push(`type ${live.type} -> ${type}`);
      body.type = type;
    }
    if (live.parent_id !== parentRef) {
      changes.push("move to new category");
      body.parent_id = parentRef;
    }
    if (ch.topic !== undefined && (live.topic ?? "") !== ch.topic && type !== 2 && type !== 13) {
      changes.push("topic");
      body.topic = ch.topic;
    }
    if (ch.slowmode !== undefined && (live.rate_limit_per_user ?? 0) !== ch.slowmode) {
      changes.push(`slowmode ${ch.slowmode}s`);
      body.rate_limit_per_user = ch.slowmode;
    }
    const cmp = resolveForCompare(wire, roleIds);
    if (!cmp || normOverwrites(cmp) !== normOverwrites(live.permission_overwrites)) {
      changes.push("permission_overwrites");
      body.permission_overwrites = wire;
    }
    if (changes.length) ops.push({ op: "update-channel", ref, id: live.id, changes, body });
  }
  if (ch.settingKey) {
    const value = live && convertible(live.type, type) ? live.id : ref;
    if (settings[ch.settingKey] !== value) ops.push({ op: "set-setting", key: ch.settingKey, value });
  }
  const panel = panelFor(ch.key);
  if (panel && (!live || !convertible(live.type, type))) ops.push({ op: "post-panel", channel: ref, panel });
  else if (panel) ops.push({ op: "note", text: `#${ch.name} exists: re-post its ${panel} panel by hand or with --repost-panels` });
}

function matchRole(r: RoleSpec, roles: LiveRole[], settings: Record<string, string>, taken: Set<string>): LiveRole | null {
  const byId = r.settingKey ? settings[r.settingKey] : undefined;
  if (byId) {
    const hit = roles.find((x) => x.id === byId && !x.managed);
    if (hit && !taken.has(hit.id)) return hit;
  }
  const names = [r.name, ...(r.aliases ?? [])];
  return roles.find((x) => !x.managed && !taken.has(x.id) && names.includes(x.name)) ?? null;
}

function matchChannel(
  s: { name: string; settingKey?: string; aliases?: string[] },
  type: number | null,
  channels: LiveChannel[],
  settings: Record<string, string>,
  used: Set<string>,
  inBridge: (c: LiveChannel) => boolean,
): LiveChannel | null {
  const ok = (c: LiveChannel) => !used.has(c.id) && !inBridge(c) && (type === null ? c.type !== 4 : c.type === type);
  const byId = s.settingKey ? settings[s.settingKey] : undefined;
  if (byId) {
    const hit = channels.find((c) => c.id === byId);
    if (hit && ok(hit)) return hit;
  }
  const names = [s.name, ...(s.aliases ?? [])];
  for (const n of names) {
    const hit = channels.find((c) => ok(c) && c.name === n);
    if (hit) return hit;
  }
  return null;
}

/** Human-readable dry-run output. */
export function renderPlan(ops: Op[]): string {
  const lines: string[] = [];
  const count = (k: Op["op"]) => ops.filter((o) => o.op === k).length;
  lines.push(
    `PLAN: ${count("create-role")} roles to create, ${count("update-role")} to update; ${count("create-category")} categories + ${count("create-channel")} channels to create, ${count("update-channel")} to update, ${count("move-to-legacy")} to move to Legacy; ${count("set-setting")} settings; ${count("post-panel")} panels. Nothing is deleted.`,
  );
  lines.push("");
  for (const o of ops) {
    switch (o.op) {
      case "update-everyone":
        lines.push(`ROLE   @everyone base permissions -> ${o.permissions} (was ${o.from})`);
        break;
      case "create-role":
        lines.push(`ROLE + ${o.body.name}`);
        break;
      case "update-role":
        lines.push(`ROLE ~ ${o.body.name} (${o.id}): ${o.changes.join("; ")}`);
        break;
      case "reorder-roles":
        lines.push(`ROLE   hierarchy (top first, under the bot): ${o.order.map((r) => r.replace("$role:", "")).join(" > ")}`);
        break;
      case "create-category":
        lines.push(`\nCAT  + ${o.body.name}`);
        break;
      case "create-channel":
        lines.push(`  CH + ${o.body.type === 2 || o.body.type === 13 ? "" : "#"}${o.body.name} [${typeName(o.body.type)}] in ${o.body.parent_id}`);
        break;
      case "update-channel":
        lines.push(`  CH ~ ${o.ref} (${o.id}): ${o.changes.join("; ")}`);
        break;
      case "move-to-legacy":
        lines.push(`  LEGACY <- ${o.name} (${o.id}): ${o.reason}`);
        break;
      case "post-panel":
        lines.push(`  POST ${o.panel} panel in ${o.channel}`);
        break;
      case "update-guild":
        lines.push(`\nGUILD  ${JSON.stringify(o.body)}`);
        break;
      case "set-setting":
        lines.push(`SETTING ${o.key} = ${o.value}`);
        break;
      case "note":
        lines.push(`NOTE   ${o.text}`);
        break;
    }
  }
  return lines.join("\n");
}

function typeName(t: number): string {
  return t === 0 ? "text" : t === 2 ? "voice" : t === 5 ? "announcement" : t === 13 ? "stage" : t === 15 ? "forum" : String(t);
}

export type { PermName };

