// ---------------------------------------------------------------------------
// Threads + embeds (server redo, 2026-10-07). Private threads (type 12) are the
// thread-mode home of tickets/live chats: they never count against the
// 50-per-category / 500-per-guild channel caps, and a private thread is
// invisible to everyone who isn't a member or holds MANAGE_THREADS on the
// parent — no category-overwrite inheritance to get wrong (2026-09-05 leak).
// ---------------------------------------------------------------------------

/** Discord thread channel types: 10 announcement thread, 11 public, 12 private. */
export const THREAD_TYPES = new Set([10, 11, 12]);

/** Create a PRIVATE, non-invitable thread under a text channel. Returns the thread id. */
export async function createPrivateThread(parentChannelId: string, name: string): Promise<string | null> {
  const res = await discordFetch(`/channels/${parentChannelId}/threads`, {
    method: "POST",
    body: { name: name.slice(0, 100) || "ticket", type: 12, invitable: false, auto_archive_duration: 10080 },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] createPrivateThread failed", parentChannelId, describeDiscordError(res?.status, res?.json));
    return null;
  }
  return (res.json as { id: string }).id;
}

/** Add a guild member to a thread (they must be able to view the parent channel). */
export async function addThreadMember(threadId: string, userId: string): Promise<boolean> {
  const res = await discordFetch(`/channels/${threadId}/thread-members/${userId}`, { method: "PUT" });
  if (!res || res.status >= 300) {
    console.error("[discord] addThreadMember failed", threadId, userId, describeDiscordError(res?.status, res?.json));
    return false;
  }
  return true;
}

/** Archive (+lock) or reopen a thread. Locked threads only accept messages from MANAGE_THREADS holders (the bot). */
export async function setThreadState(threadId: string, archived: boolean): Promise<boolean> {
  const res = await discordFetch(`/channels/${threadId}`, { method: "PATCH", body: { archived, locked: archived } });
  if (!res || res.status >= 300) {
    console.error("[discord] setThreadState failed", threadId, describeDiscordError(res?.status, res?.json));
    return false;
  }
  return true;
}

/** The raw channel type of a channel/thread id, or null if it can't be read. */
export async function getChannelType(channelId: string): Promise<number | null> {
  const res = await discordFetch(`/channels/${channelId}`);
  if (!res || res.status >= 300) return null;
  const t = (res.json as { type?: unknown }).type;
  return typeof t === "number" ? t : null;
}

export type DiscordEmbed = {
  title?: string;
  description?: string;
  url?: string;
  color?: number;
  timestamp?: string;
  fields?: Array<{ name: string; value: string; inline?: boolean }>;
  footer?: { text: string };
  image?: { url: string };
};

/**
 * Post a message with embeds/components. `allowedRoleMentions` is the ONLY way
 * a role ping goes out: allowed_mentions.parse is always empty, so text such as
 * "@everyone" inside customer-supplied content can never ping anybody.
 */
export async function postRichMessage(
  channelId: string,
  msg: { content?: string; embeds?: DiscordEmbed[]; components?: unknown[]; allowedRoleMentions?: string[] },
): Promise<string | null> {
  const res = await discordFetch(`/channels/${channelId}/messages`, {
    method: "POST",
    body: {
      content: msg.content?.slice(0, 2000),
      embeds: msg.embeds?.slice(0, 10),
      components: msg.components,
      allowed_mentions: { parse: [], roles: msg.allowedRoleMentions ?? [] },
    },
  });
  if (!res || res.status >= 300) {
    console.error("[discord] postRichMessage failed", channelId, describeDiscordError(res?.status, res?.json));
    return null;
  }
  return (res.json as { id: string }).id;
}

/** Publish a message in an announcement channel to every following server. Best-effort. */
export async function crosspostMessage(channelId: string, messageId: string): Promise<boolean> {
  const res = await discordFetch(`/channels/${channelId}/messages/${messageId}/crosspost`, { method: "POST" });
  return Boolean(res && res.status < 300);
}
