/**
 * Pure builders for every rich message the Nxeon bot posts: the status feed,
 * the What's New auto-post, the redo's panels (open-a-ticket, link-your-
 * account, rules, welcome) and the staff queue ping. No imports from
 * server-only modules so test/discord-embeds.test.ts can drive them directly.
 *
 * Content rules: Nxeon speaks as the owner (no third-party vendor names), no
 * invented numbers, and nothing customer-specific ever goes into a PUBLIC
 * channel (status / whats-new / panels carry only platform-level text).
 */

export type Embed = {
  title?: string;
  description?: string;
  url?: string;
  color?: number;
  timestamp?: string;
  fields?: Array<{ name: string; value: string; inline?: boolean }>;
  footer?: { text: string };
  image?: { url: string };
};

export const BRAND = { blue: 0x3b6be8, violet: 0x7b3fef, magenta: 0xe5197e, green: 0x34d399, amber: 0xf59e0b, red: 0xef4444, grey: 0x8a93a6 };

const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);

// --- status feed -------------------------------------------------------------

export type IncidentLike = { title: string; body?: string | null; component?: string | null; severity: string; auto?: boolean };
export type IncidentEvent = "opened" | "resolved" | "reopened" | "update";

const SEVERITY_COLOR: Record<string, number> = { down: BRAND.red, degraded: BRAND.amber, maintenance: BRAND.blue };
const SEVERITY_LABEL: Record<string, string> = { down: "Outage", degraded: "Degraded performance", maintenance: "Maintenance" };

export function incidentEmbed(i: IncidentLike, event: IncidentEvent, appUrl: string, now = new Date()): Embed {
  const resolved = event === "resolved";
  const prefix = resolved ? "Resolved" : event === "reopened" ? "Reopened" : event === "update" ? "Update" : SEVERITY_LABEL[i.severity] ?? "Incident";
  const fields = [
    { name: "Affected", value: clip(i.component || "Platform-wide", 100), inline: true },
    { name: "Status", value: resolved ? "Resolved" : SEVERITY_LABEL[i.severity] ?? i.severity, inline: true },
  ];
  return {
    title: clip(`${prefix}: ${i.title}`, 256),
    description: i.body && !resolved ? clip(i.body, 1500) : resolved ? "Everything is working normally again. Thanks for your patience." : undefined,
    url: `${appUrl}/status`,
    color: resolved ? BRAND.green : SEVERITY_COLOR[i.severity] ?? BRAND.grey,
    timestamp: now.toISOString(),
    fields,
    footer: { text: "Nxeon status · nxeon.cloud/status" },
  };
}

// --- What's New -----------------------------------------------------------------

export type ReleaseLike = {
  id: string;
  title: string;
  summary?: string | null;
  body?: string | null;
  highlights?: Array<{ title: string; description: string }>;
  heroImageUrl?: string | null;
  status: string;
  publishedAt: Date | null;
  scheduledFor: Date | null;
  createdAt: Date;
  audience?: string | null;
  regions?: string[];
  serviceTypes?: string[];
};

/** The moment a release went (or goes) live — same rule as lib/whats-new/core.ts liveDate/effectiveStatus. */
export function releaseLiveAt(r: ReleaseLike): Date | null {
  if (r.status === "PUBLISHED") return r.publishedAt ?? r.createdAt;
  if (r.status === "SCHEDULED" && r.scheduledFor) return r.scheduledFor;
  return null;
}

/**
 * Which releases to auto-post publicly: live now, live after the watermark
