/**
 * Applies a plan from lib/discord-redo/plan.ts. Every side effect goes through
 * injected deps (`call` = one Discord REST request, `setSetting`) so the whole
 * executor runs against an in-memory fake guild in
 * test/discord-redo-plan.test.ts. The only real caller is
 * scripts/discord-redo-apply.ts, and only with --apply plus the owner-approval
 * guards described there. Never deletes anything.
 */
import { linkAccountPanel, openTicketPanel, rulesPanel, welcomePanel } from "../discord-embeds";
import type { Op, WireOverwrite } from "./plan";

export type RedoDeps = {
  guildId: string;
  botRoleId: string | null;
  /** Live position of the bot's role (roles are placed just under it). */
  botRolePosition: number | null;
  appUrl: string;
  call: (method: "GET" | "POST" | "PATCH" | "PUT", path: string, body?: unknown) => Promise<{ status: number; json: unknown }>;
  setSetting: (key: string, value: string) => Promise<void>;
  log: (line: string) => void;
};

export type RedoResult = { applied: number; failed: Array<{ op: string; error: string }>; refs: Record<string, string> };

export async function executeRedoPlan(ops: Op[], deps: RedoDeps): Promise<RedoResult> {
  const refs: Record<string, string> = {};
  if (deps.botRoleId) refs["$bot"] = deps.botRoleId;
  for (const o of ops) if (o.op === "bind") refs[o.ref] = o.id;
  const result: RedoResult = { applied: 0, failed: [], refs };
  let legacyOverwrites: WireOverwrite[] | null = null;

  const resolve = (v: unknown): unknown => {
    if (typeof v === "string" && v.startsWith("$")) {
      const id = refs[v];
      if (!id) throw new Error(`unresolved reference ${v}`);
      return id;
    }
    if (Array.isArray(v)) return v.map(resolve);
    if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolve(x)]));
    return v;
  };
  const ok = (r: { status: number; json: unknown }, what: string) => {
    if (r.status >= 300) throw new Error(`${what}: ${r.status} ${JSON.stringify(r.json).slice(0, 300)}`);
    return r.json as { id?: string };
  };
  const g = deps.guildId;

  for (const o of ops) {
    try {
      switch (o.op) {
        case "bind":
        case "note":
          continue;
        case "update-everyone":
          ok(await deps.call("PATCH", `/guilds/${g}/roles/${g}`, { permissions: o.permissions }), "update @everyone");
          break;
        case "create-role": {
          const j = ok(await deps.call("POST", `/guilds/${g}/roles`, o.body), `create role ${o.body.name}`);
          refs[o.ref] = j.id!;
          break;
        }
        case "update-role":
          ok(await deps.call("PATCH", `/guilds/${g}/roles/${o.id}`, o.body), `update role ${o.id}`);
          break;
        case "reorder-roles": {
          const top = (deps.botRolePosition ?? o.order.length + 1) - 1;
          const body = o.order
            .map((ref, i) => ({ id: refs[ref], position: Math.max(1, top - i) }))
            .filter((x): x is { id: string; position: number } => Boolean(x.id));
          ok(await deps.call("PATCH", `/guilds/${g}/roles`, body), "reorder roles");
          break;
        }
        case "create-category": {
          const body = resolve(o.body) as { permission_overwrites: WireOverwrite[] };
          const j = ok(await deps.call("POST", `/guilds/${g}/channels`, body), `create category ${o.body.name}`);
          refs[o.ref] = j.id!;
          if (o.ref === "$legacy") legacyOverwrites = body.permission_overwrites;
          break;
        }
        case "create-channel": {
          const j = ok(await deps.call("POST", `/guilds/${g}/channels`, resolve(o.body)), `create channel ${o.body.name}`);
          refs[o.ref] = j.id!;
          break;
        }
        case "update-channel":
          ok(await deps.call("PATCH", `/channels/${o.id}`, resolve(o.body)), `update channel ${o.id}`);
          break;
        case "move-to-legacy":
          ok(
            await deps.call("PATCH", `/channels/${o.id}`, { parent_id: resolve("$legacy"), permission_overwrites: legacyOverwrites ?? undefined }),
            `legacy ${o.name}`,
          );
          break;
        case "post-panel": {
          const channel = resolve(o.channel) as string;
          const panel =
            o.panel === "open_ticket" ? openTicketPanel(deps.appUrl) : o.panel === "link_account" ? linkAccountPanel(deps.appUrl) : o.panel === "rules" ? rulesPanel() : welcomePanel(deps.appUrl);
          ok(await deps.call("POST", `/channels/${channel}/messages`, { ...panel, allowed_mentions: { parse: [] } }), `panel ${o.panel}`);
          break;
        }
        case "update-guild":
          ok(await deps.call("PATCH", `/guilds/${g}`, resolve(o.body)), "update guild");
          break;
        case "set-setting":
          await deps.setSetting(o.key, resolve(o.value) as string);
          break;
      }
      result.applied++;
      deps.log(`ok   ${o.op}${"ref" in o ? ` ${o.ref}` : ""}`);
    } catch (e) {
      const error = e instanceof Error ? e.message : String(e);
      result.failed.push({ op: o.op, error });
      deps.log(`FAIL ${o.op}: ${error}`);
    }
  }
  return result;
}

