/**
 * Discord server redo: show (default) or apply the new server structure.
 *
 *   npx tsx scripts/discord-redo-apply.ts                       # DRY RUN: GET guild + read settings, print the plan
 *   npx tsx scripts/discord-redo-apply.ts --snapshot guild.json # DRY RUN from a saved {channels, roles, guild:{id}} file (no network)
 *   npx tsx scripts/discord-redo-apply.ts --json                # plan as JSON
 *
 *   # ONLY after the owner approves the printed plan:
 *   NXEON_DISCORD_REDO_APPROVED=yes NXEON_DB_TARGET=nxeon \
 *     npx tsx scripts/discord-redo-apply.ts --apply --confirm-guild=<guild id>
 *
 * Spec: lib/discord-redo/spec.ts. Planner: lib/discord-redo/plan.ts. Executor:
 * lib/discord-redo/execute.ts. Rationale: /root/agent-notes/discord-redo/PLAN.md.
 * Nothing is ever deleted; the support bridge's ticket / live-chat / archive
 * categories are never touched. Needs DATABASE_URL + AUTH_SECRET for a live
 * read (bot token is decrypted in memory, never printed).
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
if (!existsSync(join(shimDir, "index.js"))) {
  mkdirSync(shimDir, { recursive: true });
  writeFileSync(join(shimDir, "index.js"), "module.exports = {};\n");
  writeFileSync(join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js"}\n');
}

function arg(name: string): string | undefined {
  const hit = process.argv.find((a) => a === `--${name}` || a.startsWith(`--${name}=`));
  if (!hit) return undefined;
  if (hit.includes("=")) return hit.slice(hit.indexOf("=") + 1);
  const i = process.argv.indexOf(hit);
  return process.argv[i + 1] && !process.argv[i + 1].startsWith("--") ? process.argv[i + 1] : "true";
}

type RawRole = { id: string; name: string; permissions: string; color: number; hoist: boolean; mentionable: boolean; managed: boolean; position: number; tags?: { bot_id?: string } };

async function main() {
  const { planServerRedo, renderPlan } = await import("../lib/discord-redo/plan");
  const { NXEON_SERVER_SPEC } = await import("../lib/discord-redo/spec");
  const apply = process.argv.includes("--apply");
  const snapshot = arg("snapshot");

  let guildId: string;
  let channels: any[];
  let roles: RawRole[];
  let settings: Record<string, string> = {};
  let appId = "";

  if (snapshot) {
    if (apply) throw new Error("--apply cannot be combined with --snapshot");
    const snap = JSON.parse(readFileSync(snapshot, "utf8"));
    channels = snap.channels;
    roles = snap.roles;
    guildId = snap.guild?.id ?? roles.reduce((a, r) => (r.position === 0 ? r.id : a), "");
    settings = snap.settings ?? {};
    appId = snap.applicationId ?? "";
  } else {
    const d = await import("../lib/discord");
    const { getAllSettings } = await import("../lib/settings");
    const all = await getAllSettings();
    for (const [k, v] of Object.entries(all)) if (k.startsWith("discord_") && k !== "discord_bot_token" && k !== "discord_client_secret") settings[k] = v;
    guildId = await d.discordGuildId();
    appId = await d.discordApplicationId();
    const c = await d.discordFetch(`/guilds/${guildId}/channels`);
    const r = await d.discordFetch(`/guilds/${guildId}/roles`);
    if (!c || c.status >= 300 || !r || r.status >= 300) throw new Error("could not read the guild (bot token / guild id?)");
    channels = c.json as any[];
    roles = r.json as RawRole[];
  }

  const bot = roles.find((r) => r.managed && appId && r.tags?.bot_id === appId) ?? roles.find((r) => r.managed && r.name === "Nxeon Support") ?? null;
  const ops = planServerRedo({ spec: NXEON_SERVER_SPEC, guild: { id: guildId, channels, roles }, settings, botRoleId: bot?.id ?? null });

  if (process.argv.includes("--json")) console.log(JSON.stringify(ops, null, 2));
  else console.log(renderPlan(ops));

  if (!apply) {
    console.log("\nDRY RUN: nothing was sent to Discord and no setting was written.");
    return;
  }

  // ---- apply: three independent guards ----------------------------------------------------
  if (process.env.NXEON_DISCORD_REDO_APPROVED !== "yes") throw new Error("refusing: set NXEON_DISCORD_REDO_APPROVED=yes once the owner approved this exact plan");
  if (arg("confirm-guild") !== guildId) throw new Error(`refusing: pass --confirm-guild=${guildId} to confirm the target guild`);
  const { assertDbTarget } = await import("./db-target-guard");
  assertDbTarget("discord-redo-apply");

  const d = await import("../lib/discord");
  const { setSetting } = await import("../lib/settings");
  const { executeRedoPlan } = await import("../lib/discord-redo/execute");
  const res = await executeRedoPlan(ops, {
    guildId,
    botRoleId: bot?.id ?? null,
    botRolePosition: bot?.position ?? null,
    appUrl: (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, ""),
    call: async (method, path, body) => {
      const r = await d.discordFetch(path, { method, body });
      if (!r) throw new Error("no bot token");
      await new Promise((ok) => setTimeout(ok, 350)); // stay well under per-route limits
      return r;
    },
    setSetting,
    log: (l) => console.log(l),
  });
  console.log(`\napplied ${res.applied}, failed ${res.failed.length}`);
  if (res.failed.length) process.exitCode = 1;
}

main()
  .catch((e) => {
    console.error(e instanceof Error ? e.message : e);
    process.exitCode = 1;
  })
  .finally(() => setTimeout(() => process.exit(process.exitCode ?? 0), 50));

