import "server-only";
import type { Role } from "@prisma/client";
import { db } from "./db";
import { canAccess } from "./rbac";
import {
  discordEnabled,
  postChannelMessage,
  setChannelPermissionOverwrite,
  PERMISSION_BIT,
} from "./discord";
import { createBridgeChannel, maybeReconcileDiscordBridge, moveBridgeChannel, notifySupportQueueFallback } from "./discord-category-pool";
import { writeTicketReply, writeChatReply, createTicketCore } from "./reply-core";

/** VIEW_CHANNEL + SEND_MESSAGES + READ_MESSAGE_HISTORY, OR'd as a single Discord permission bitfield string. */
const CUSTOMER_CHANNEL_ACCESS = (
  BigInt(PERMISSION_BIT.VIEW_CHANNEL) | BigInt(PERMISSION_BIT.SEND_MESSAGES) | BigInt(PERMISSION_BIT.READ_MESSAGE_HISTORY)
).toString();

/**
 * Grant a LINKED customer direct access to their own ticket/chat channel
 * (a per-member overwrite layered on top of the category's existing
 * staff-only baseline — Discord resolves a member-specific allow over a
 * role-based deny, so this never needs to touch @everyone or risk the
 * bot-lockout failure mode a category-level edit can hit) and post a
 * one-line account-summary so staff can see exactly who they're talking to
 * without leaving Discord. A customer with no `discordUserId` yet (hasn't
 * completed account linking) gets neither — their channel stays exactly as
 * staff-only as it always has, no regression.
 */
async function grantCustomerAccessAndSummary(channelId: string, userId: string): Promise<void> {
  try {
    const user = await db.user.findUnique({
      where: { id: userId },
      select: { discordUserId: true, name: true, email: true } as any,
    });
    const discordUserId = (user as any)?.discordUserId as string | null | undefined;
    if (!discordUserId) return;

    await setChannelPermissionOverwrite(channelId, { id: discordUserId, type: 1, allow: CUSTOMER_CHANNEL_ACCESS, deny: "0" });

    const [hasVps, hasGame, hasHosting, openTickets] = await Promise.all([
      db.server.findFirst({ where: { userId, gamePlanId: null }, select: { id: true } }),
      db.server.findFirst({ where: { userId, gamePlanId: { not: null } }, select: { id: true } }),
      db.hostingAccount.findFirst({ where: { userId }, select: { id: true } }),
      db.ticket.count({ where: { userId, status: { not: "CLOSED" } } }),
    ]);
    const badges = [hasVps && "🖥️ VPS", hasGame && "🎮 Game Server", hasHosting && "🌐 Hosting"].filter(Boolean).join(" · ") || "no active services";
    await postChannelMessage(
      channelId,
      `🔗 **Linked Nxeon account:** ${(user as any)?.name ?? "?"}${(user as any)?.email ? ` (${(user as any).email})` : ""} — ${badges} — ${openTickets} open ticket${openTickets === 1 ? "" : "s"}`,
    );
  } catch (e) {
    console.error("[discord-bridge] grantCustomerAccessAndSummary failed (non-fatal)", userId, e);
  }
}

