 * outage, and they are invisible to anyone who isn't a member (or a
 * MANAGE_THREADS holder) — no category overwrite to get wrong. Runtime half:
 * lib/discord-threads.ts. Tests: test/discord-thread-plan.test.ts.
 */

export type BridgeMode = "channels" | "threads";

/** Thread mode only when asked for AND the host channel for that kind is configured; anything else stays on channels. */
export function chooseBridgeMode(modeSetting: string | null | undefined, hostChannelId: string | null | undefined): BridgeMode {
  return (modeSetting ?? "").trim().toLowerCase() === "threads" && /^\d{5,25}$/.test((hostChannelId ?? "").trim()) ? "threads" : "channels";
}

/** "ticket-1a2b3c4d · Server won't start" — the short id first so staff can search it; subject clipped to Discord's 100-char limit. */
export function bridgeThreadName(kind: "ticket" | "chat", id: string, subject?: string | null): string {
  const base = `${kind}-${id.slice(-8)}`;
  const s = (subject ?? "").replace(/[\r\n]+/g, " ").trim();
  return (s ? `${base} · ${s}` : base).slice(0, 100);
}

/** Thread channel types: 10 announcement thread, 11 public thread, 12 private thread. */
export function isThreadType(t: number | null | undefined): boolean {
  return t === 10 || t === 11 || t === 12;
}

/**
 * Which linked staff accounts to add to a new private thread so they get
 * Discord notifications for it (MANAGE_THREADS lets them SEE every thread, but
 * Discord only notifies thread MEMBERS). Support-capable roles only, de-duped,
 * capped so a big team doesn't mean dozens of REST calls per ticket.
 */
export function staffToAutoAdd(
  staff: Array<{ discordUserId: string | null; role: string; suspended?: boolean }>,
  canSupport: (role: string) => boolean,
  max = 8,
): string[] {
  const out: string[] = [];
  for (const s of staff) {
    if (!s.discordUserId || s.suspended || !canSupport(s.role)) continue;
    if (!out.includes(s.discordUserId)) out.push(s.discordUserId);
    if (out.length >= max) break;
  }
  return out;
}
