import "server-only";
import type { Role } from "@prisma/client";
import { db } from "./db";
import { canAccess } from "./rbac";
import { getSetting, getSettingBool } from "./settings";
import { addThreadMember, createPrivateThread, getChannelType, postRichMessage, setThreadState } from "./discord";
import { bridgeThreadName, chooseBridgeMode, isThreadType, staffToAutoAdd, type BridgeMode } from "./discord-thread-plan";
import { queuePing } from "./discord-embeds";

/**
 * Runtime half of the bridge's thread mode (pure rules: lib/discord-thread-plan.ts).
 * Off unless Setting discord_bridge_mode = "threads" AND the host channel
 * (discord_channel_ticket_desk_id / discord_channel_chat_desk_id, written by
 * scripts/discord-redo-apply.ts) is set. Existing channel-mode tickets keep
 * their channels; only NEW items get threads. Best-effort like the rest of the
 * bridge: never throws to callers.
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

export async function bridgeModeFor(kind: "ticket" | "chat"): Promise<{ mode: BridgeMode; hostChannelId: string }> {
  const [mode, host] = await Promise.all([
    getSetting("discord_bridge_mode", "channels"),
    getSetting(kind === "ticket" ? "discord_channel_ticket_desk_id" : "discord_channel_chat_desk_id", ""),
  ]);
  return { mode: chooseBridgeMode(mode, host), hostChannelId: host.trim() };
}

/** Create the private thread, add linked support staff, and ping #support-queue. Returns the thread id. */
export async function openBridgeThread(args: {
  kind: "ticket" | "chat";
  id: string;
  hostChannelId: string;
  subject?: string;
  priority?: string;
}): Promise<string | null> {
  const threadId = await createPrivateThread(args.hostChannelId, bridgeThreadName(args.kind, args.id, args.subject));
  if (!threadId) return null;
  try {
    if (await getSettingBool("discord_thread_auto_add_staff", true)) {
      const staff = await db.user.findMany({
        where: { discordUserId: { not: null }, role: { not: "CUSTOMER" as Role } } as any,
        select: { discordUserId: true, role: true, suspended: true } as any,
        take: 50,
      });
      for (const uid of staffToAutoAdd(staff as any, (r) => canAccess(r as Role, "support"))) await addThreadMember(threadId, uid);
    }
    const queue = (await getSetting("discord_channel_support_queue_id", "")).trim();
    if (queue) {
      const supportRoleId = (await getSetting("discord_role_customer_support_id", "")).trim() || undefined;
      const ping = queuePing({
        kind: args.kind,
        threadId,
        subject: args.subject,
        priority: args.priority,
        supportRoleId,
        appUrl: APP_URL,
        adminPath: args.kind === "ticket" ? `/admin/support/${args.id}` : "/admin/chat",
      });
      await postRichMessage(queue, ping);
    }
  } catch (e) {
    console.error("[discord-threads] post-create steps failed (non-fatal)", args.kind, args.id, e);
  }
  return threadId;
}

/** Archive+lock (close) or reopen a mirrored item if it is a thread. Returns false when the id is NOT a thread (caller falls back to channel handling). */
export async function setThreadArchivedIfThread(id: string, archived: boolean): Promise<boolean> {
  const t = await getChannelType(id);
  if (!isThreadType(t)) return false;
  await setThreadState(id, archived);
  return true;
}

export { addThreadMember, isThreadType };
