p='lib/discord-bridge.ts'; s=open(p).read()
start=s.index('/**\n * @param discordUserId The REAL Discord user id')
s=s[:start]+'''/**
 * Ticket replies only: who may answer a ticket from Discord, and as what.
 * Support staff (same rule as resolveDiscordReplyActor) reply AS STAFF. The
 * ticket's OWN customer, once their Discord account is linked, replies AS THE
 * CUSTOMER (thread mode puts them in their ticket thread; the bot is
 * HTTP-only and can't read typed messages, so the Reply button is how a
 * customer's answer reaches the Nxeon ticket). Anyone else is rejected.
 * Pure, so test/discord-thread-plan.test.ts covers it without a database.
 */
export function resolveDiscordTicketReplyActor(
  linkedUser: { id: string; role: Role; suspended?: boolean } | null,
  ticketOwnerId: string | null,
): { actorId: string; asStaff: boolean } | { error: string } {
  if (!linkedUser) return { error: NOT_LINKED_MSG };
  if (linkedUser.suspended) return { error: "⚠️ This account is suspended." };
  if (ticketOwnerId && linkedUser.id === ticketOwnerId) return { actorId: linkedUser.id, asStaff: false };
  const staff = resolveDiscordReplyActor(linkedUser);
  if ("error" in staff) return staff;
  return { actorId: staff.actorId, asStaff: true };
}

/** The visible acknowledgement doubles as the transcript line in Discord: who said what. */
export function replyEchoText(asStaff: boolean, name: string | null | undefined, text: string): string {
  const who = asStaff ? `🛟 **Staff${name ? ` (${name})` : ""}**` : "👤 **Customer**";
  return `${who}: ${text}`.slice(0, 2000);
}

/**
 * @param discordUserId The REAL Discord user id of whoever submitted the
 *   reply modal (from `extractInteractionUserId` on the verified interaction
 *   payload — see app/api/webhooks/discord/route.ts). `null` if it couldn't
 *   be extracted, which resolves the same as "not linked".
 */
export async function submitDiscordReply(
  kind: BridgeKind,
  id: string,
  replyText: string,
  discordUserId: string | null,
): Promise<string> {
  const text = replyText.trim();
  if (!text) return "⚠️ Empty reply — nothing sent.";

  try {
    const linkedUser = discordUserId
      ? ((await db.user.findUnique({ where: { discordUserId } as any, select: { id: true, role: true, name: true, suspended: true } })) as
          | { id: string; role: Role; name: string | null; suspended: boolean }
          | null)
      : null;

    if (kind === "ticket") {
      const ticket = await db.ticket.findUnique({ where: { id }, select: { userId: true } });
      if (!ticket) return "⚠️ Ticket not found.";
      const resolved = resolveDiscordTicketReplyActor(linkedUser, ticket.userId);
      if ("error" in resolved) {
        console.error("[discord-bridge] ticket reply rejected", { id, discordUserId });
        return resolved.error;
      }
      const result = await writeTicketReply({
        actorId: resolved.actorId,
        actorIsSupportStaff: resolved.asStaff,
        ticketId: id,
        body: text,
      });
      if (result.error) return `⚠️ ${result.error}`;
      return replyEchoText(resolved.asStaff, linkedUser?.name, text);
    }

    const resolved = resolveDiscordReplyActor(linkedUser);
    if ("error" in resolved) {
      console.error("[discord-bridge] reply rejected — no linked staff account", { kind, id, discordUserId });
      return resolved.error;
    }
    const result = await writeChatReply({ conversationId: id, body: text, staffId: resolved.actorId });
    if (result.error) return `⚠️ ${result.error}`;
    return replyEchoText(true, linkedUser?.name, text);
  } catch (e) {
    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
    return "⚠️ Something went wrong sending that reply — check the admin panel.";
  }
}
'''
open(p,'w').write(s)
