import "server-only";
import { db } from "./db";
import { getSetting, getSettingBool, setSetting } from "./settings";
import { discordEnabled, postRichMessage, crosspostMessage } from "./discord";
import { maybeReconcileDiscordBridge } from "./discord-category-pool";
import { syncAllLinkedDiscordRoles } from "./discord-roles";
import { releasesToPost, whatsNewEmbed, type ReleaseLike } from "./discord-embeds";
import { parseStoredHighlights } from "./whats-new/core";

/**
 * Periodic Discord upkeep, run from the WEB process (lib/discord.ts and
 * friends are `server-only`, so not the plain-tsx worker). Kicked, fire-and-
 * forget, by every bridge mirror call; each job self-throttles per process:
 *   - bridge reconcile (15 min) — lib/discord-category-pool.ts
 *   - badge-role resync for all linked accounts (6 h) — lib/discord-roles.ts
 *   - What's New auto-post to #whats-new (10 min, default OFF)
 * Never throws, never awaited by a request.
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const ROLE_SYNC_EVERY_MS = 6 * 60 * 60 * 1000;
const WHATS_NEW_EVERY_MS = 10 * 60 * 1000;
const last = { roles: 0, whatsNew: 0 };
const busy = { roles: false, whatsNew: false };

export function kickDiscordHousekeeping(now = Date.now()): void {
  maybeReconcileDiscordBridge(now);
  if (!busy.roles && now - last.roles >= ROLE_SYNC_EVERY_MS) {
    last.roles = now;
    busy.roles = true;
    void (async () => {
      try {
        if (await getSettingBool("discord_role_resync_enabled", true)) await syncAllLinkedDiscordRoles();
      } catch (e) {
        console.error("[discord-housekeeping] role resync failed (non-fatal)", e);
      } finally {
        busy.roles = false;
      }
    })();
  }
  if (!busy.whatsNew && now - last.whatsNew >= WHATS_NEW_EVERY_MS) {
    last.whatsNew = now;
    busy.whatsNew = true;
    void postWhatsNewToDiscord()
      .catch((e) => console.error("[discord-housekeeping] whats-new post failed (non-fatal)", e))
      .finally(() => {
        busy.whatsNew = false;
      });
  }
}

/**
 * Post newly-live, untargeted What's New releases to #whats-new as embeds.
 * OFF unless Setting discord_whats_new_autopost=true and
 * discord_channel_whats_new_id is set. The first run after switching on only
 * records "now" as the watermark, so older releases are never back-posted.
 */
export async function postWhatsNewToDiscord(now = new Date()): Promise<number> {
  if (!(await discordEnabled())) return 0;
  if (!(await getSettingBool("discord_whats_new_autopost", false))) return 0;
  const channelId = (await getSetting("discord_channel_whats_new_id", "")).trim();
  if (!channelId) return 0;
  const wmRaw = (await getSetting("discord_whats_new_watermark", "")).trim();
  if (!wmRaw || Number.isNaN(Date.parse(wmRaw))) {
    await setSetting("discord_whats_new_watermark", now.toISOString());
    return 0;
  }
  const watermark = new Date(wmRaw);
  const rows = await db.updateAnnouncement.findMany({
    where: {
      OR: [
        { status: "PUBLISHED", publishedAt: { gt: watermark } },
        { status: "SCHEDULED", scheduledFor: { gt: watermark, lte: now } },
      ],
    },
    orderBy: { createdAt: "asc" },
    take: 20,
  });
  const releases: ReleaseLike[] = rows.map((r) => ({
    id: r.id,
    title: r.title,
    summary: r.summary,
    body: r.body,
    highlights: parseStoredHighlights(r.highlights).map((h) => ({ title: h.title, description: h.description })),
    heroImageUrl: r.heroImageUrl,
    status: r.status,
    publishedAt: r.publishedAt,
    scheduledFor: r.scheduledFor,
    createdAt: r.createdAt,
    audience: r.audience,
    regions: r.regions,
    serviceTypes: r.serviceTypes,
  }));
  const pingRole = (await getSetting("discord_role_ping_announcements_id", "")).trim();
  let posted = 0;
  let newWatermark = watermark;
  for (const r of releasesToPost(releases, watermark, now)) {
    const id = await postRichMessage(channelId, {
      content: pingRole ? `<@&${pingRole}>` : undefined,
      embeds: [whatsNewEmbed(r, APP_URL)],
      allowedRoleMentions: pingRole ? [pingRole] : [],
    });
    if (!id) break; // keep the watermark so it retries next time
    await crosspostMessage(channelId, id);
    posted++;
    const at = r.status === "PUBLISHED" ? r.publishedAt ?? r.createdAt : r.scheduledFor!;
    if (at > newWatermark) newWatermark = at;
    await setSetting("discord_whats_new_watermark", newWatermark.toISOString());
  }
  // Targeted releases are skipped, never posted: move the watermark past everything that is live now.
  if (posted === releasesToPost(releases, watermark, now).length) {
    const latestLive = releases
      .map((r) => (r.status === "PUBLISHED" ? r.publishedAt : r.scheduledFor))
      .filter((d): d is Date => Boolean(d) && d!.getTime() <= now.getTime())
      .reduce((a, d) => (d > a ? d : a), newWatermark);
    if (latestLive > watermark) await setSetting("discord_whats_new_watermark", latestLive.toISOString());
  }
  return posted;
}
EOF
