        { status: "SCHEDULED", scheduledFor: { gt: watermark, lte: now } },
      ],
    },
    orderBy: { createdAt: "asc" },
    take: 20,
  });
  const releases: ReleaseLike[] = rows.map((r) => ({
    id: r.id,
    title: r.title,
    summary: r.summary,
    body: r.body,
    highlights: parseStoredHighlights(r.highlights).map((h) => ({ title: h.title, description: h.description })),
    heroImageUrl: r.heroImageUrl,
    status: r.status,
    publishedAt: r.publishedAt,
    scheduledFor: r.scheduledFor,
    createdAt: r.createdAt,
    audience: r.audience,
    regions: r.regions,
    serviceTypes: r.serviceTypes,
  }));
  const pingRole = (await getSetting("discord_role_ping_announcements_id", "")).trim();
  let posted = 0;
  let newWatermark = watermark;
  for (const r of releasesToPost(releases, watermark, now)) {
    const id = await postRichMessage(channelId, {
      content: pingRole ? `<@&${pingRole}>` : undefined,
      embeds: [whatsNewEmbed(r, APP_URL)],
      allowedRoleMentions: pingRole ? [pingRole] : [],
    });
    if (!id) break; // keep the watermark so it retries next time
    await crosspostMessage(channelId, id);
    posted++;
    const at = r.status === "PUBLISHED" ? r.publishedAt ?? r.createdAt : r.scheduledFor!;
    if (at > newWatermark) newWatermark = at;
    await setSetting("discord_whats_new_watermark", newWatermark.toISOString());
  }
  // Targeted releases are skipped, never posted: move the watermark past everything that is live now.
  if (posted === releasesToPost(releases, watermark, now).length) {
    const latestLive = releases
      .map((r) => (r.status === "PUBLISHED" ? r.publishedAt : r.scheduledFor))
      .filter((d): d is Date => Boolean(d) && d!.getTime() <= now.getTime())
      .reduce((a, d) => (d > a ? d : a), newWatermark);
    if (latestLive > watermark) await setSetting("discord_whats_new_watermark", latestLive.toISOString());
  }
  return posted;
}
EOF
