import { test } from "node:test";
import assert from "node:assert/strict";
import { planServerRedo, renderPlan, type LiveChannel, type LiveGuild, type LiveRole, type Op } from "../lib/discord-redo/plan.ts";
import { executeRedoPlan } from "../lib/discord-redo/execute.ts";
import { NXEON_SERVER_SPEC } from "../lib/discord-redo/spec.ts";
import { DANGEROUS, bits, namesOf } from "../lib/discord-redo/permissions.ts";

/**
 * The Discord server redo planner + executor, run against an in-memory fake
 * guild shaped like the live "Nxeon Cloud" guild (read-only GET, 2026-10-07).
 * Nothing here talks to Discord.
 */

const G = "900000000000000000";
const BOT = "900000000000000001";
let seq = 900000000000001000n;
const id = () => (seq++).toString();

const DEFAULT_MEMBER = "2248473465835073"; // what every live badge role holds today (incl. MENTION_EVERYONE)

function role(name: string, extra: Partial<LiveRole> = {}): LiveRole {
  return { id: id(), name, permissions: DEFAULT_MEMBER, color: 0, hoist: false, mentionable: true, managed: false, position: 1, ...extra };
}

function fakeGuild() {
  const roles: LiveRole[] = [
    { id: G, name: "@everyone", permissions: "2222085186637377", color: 0, hoist: false, mentionable: false, managed: false, position: 0 },
    { id: BOT, name: "Nxeon Support", permissions: "8", color: 0, hoist: false, mentionable: false, managed: true, position: 12 },
  ];
  const settings: Record<string, string> = {};
  const add = (key: string, r: LiveRole) => {
    roles.push(r);
    settings[key] = r.id;
    return r.id;
  };
  add("discord_role_owner_id", role("👑 Owner"));
  add("discord_role_admin_id", role("🛡️ Admin"));
  add("discord_role_manager_id", role("🧭 Manager"));
  const staff = add("discord_role_staff_id", role("⚙️ Staff"));
  const support = add("discord_role_customer_support_id", role("🎧 Customer Support"));
  add("discord_role_partner_id", role("💎 Partner"));
  add("discord_role_verified_id", role("✅ Verified Customer"));
  add("discord_role_vps_owner_id", role("🖥️ VPS Owner"));
  add("discord_role_game_owner_id", role("🎮 Game Server Owner"));
  add("discord_role_hosting_id", role("🌐 Hosting Customer"));

  const channels: LiveChannel[] = [];
  const cat = (key: string | null, name: string, ow: LiveChannel["permission_overwrites"] = []) => {
    const c = { id: id(), name, type: 4, parent_id: null, permission_overwrites: ow };
    channels.push(c);
    if (key) settings[key] = c.id;
    return c.id;
  };
  const ch = (parent: string, name: string, type = 0) => {
    const c = { id: id(), name, type, parent_id: parent, permission_overwrites: [] };
    channels.push(c);
    return c.id;
  };
  const privateOw = [{ id: G, type: 0, allow: "0", deny: "1024" }, { id: staff, type: 0, allow: "1024", deny: "0" }, { id: support, type: 0, allow: "1024", deny: "0" }];
  const welcome = cat("discord_category_welcome_id", "📢 WELCOME");
  settings.discord_channel_status_id = ch(welcome, "nxeon-server-status");
  ch(welcome, "welcome");
  ch(welcome, "announcements");
  const community = cat("discord_category_community_id", "💬 COMMUNITY");
  ["general", "introductions", "showcase", "off-topic"].forEach((n) => ch(community, n));
  const support2 = cat("discord_category_support_id", "🛠️ SUPPORT");
  ["support-help", "knowledge-base", "bot-commands"].forEach((n) => ch(support2, n));
  const games = cat("discord_category_games_id", "🎮 GAME SERVERS");
  ch(games, "game-server-chat");
  const voice = cat("discord_category_voice_id", "🔊 VOICE");
  ["General", "Support Voice", "AFK / Lounge"].forEach((n) => ch(voice, n, 2));
  const hq = cat("discord_category_staff_id", "🔒 STAFF HQ", privateOw);
  ["staff-announcements", "staff-chat", "support-queue", "bot-logs"].forEach((n) => ch(hq, n));
  const meet = cat("discord_category_meetings_id", "🗓️ MEETINGS", privateOw);
  ch(meet, "meeting-notes");
  ch(meet, "Staff Meeting Room", 2);
  const mgmt = cat("discord_category_management_id", "🧭 MANAGEMENT", privateOw);
  ch(mgmt, "leadership");
  const alerts = cat(null, "📡 Alerts");
  ch(alerts, "status-alerts");
  // the support bridge's categories, full of per-ticket channels
  const tickets = cat("discord_category_tickets_id", "🎫 Support Tickets", privateOw);
  const chats = cat("discord_category_livechat_id", "💬 Live Chat", privateOw);
  const archived = cat("discord_category_archived_id", "🗄️ Archived", privateOw);
  for (let i = 0; i < 50; i++) {
    ch(tickets, `ticket-${i}`);
    ch(chats, `chat-${i}`);
    ch(archived, `ticket-old-${i}`);
  }
  const guild: LiveGuild = { id: G, channels, roles };
  return { guild, settings, bridge: new Set([tickets, chats, archived]) };
}

/** Minimal in-memory Discord: applies exactly the REST calls the executor makes. */
function fakeDiscord(guild: LiveGuild) {
  const calls: Array<{ method: string; path: string }> = [];
  const call = async (method: string, path: string, body?: any) => {
    calls.push({ method, path });
    let m: RegExpMatchArray | null;
    if (method === "POST" && path === `/guilds/${G}/roles`) {
      const r: LiveRole = { id: id(), managed: false, position: 1, ...body };
      guild.roles.push(r);
      return { status: 200, json: r };
    }
    if (method === "PATCH" && path === `/guilds/${G}/roles`) {
      for (const p of body) {
        const r = guild.roles.find((x) => x.id === p.id);
        if (r) r.position = p.position;
      }
      return { status: 200, json: guild.roles };
    }
    if (method === "PATCH" && (m = path.match(/^\/guilds\/\d+\/roles\/(\d+)$/))) {
      const r = guild.roles.find((x) => x.id === m![1]);
      if (!r) return { status: 404, json: {} };
      Object.assign(r, body);
      return { status: 200, json: r };
    }
    if (method === "POST" && path === `/guilds/${G}/channels`) {
      const c: LiveChannel = { id: id(), parent_id: null, ...body, permission_overwrites: (body.permission_overwrites ?? []).map((o: any) => ({ ...o })) };
      guild.channels.push(c);
      return { status: 200, json: c };
    }
    if (method === "PATCH" && (m = path.match(/^\/channels\/(\d+)$/))) {
      const c = guild.channels.find((x) => x.id === m![1]);
      if (!c) return { status: 404, json: {} };
      Object.assign(c, body);
      return { status: 200, json: c };
    }
    if (method === "PATCH" && path === `/guilds/${G}`) return { status: 200, json: {} };
    if (method === "POST" && /^\/channels\/\d+\/messages$/.test(path)) return { status: 200, json: { id: id() } };
    return { status: 400, json: { message: `fake: unhandled ${method} ${path}` } };
  };
  return { call, calls };
}

function plan() {
  const f = fakeGuild();
  const ops = planServerRedo({ spec: NXEON_SERVER_SPEC, guild: f.guild, settings: f.settings, botRoleId: BOT });
  return { ...f, ops };
}

const wireOf = (ops: Op[], ref: string) => {
  const o = ops.find((x) => (x.op === "create-channel" || x.op === "create-category" || x.op === "update-channel") && x.ref === ref) as any;
  return o?.body?.permission_overwrites as Array<{ id: string; allow: string; deny: string }> | undefined;
};

test("the plan never deletes and never touches the bridge's ticket/chat/archive categories", () => {
  const { ops, guild, bridge } = plan();
  const bridgeChildren = new Set(guild.channels.filter((c) => c.parent_id && bridge.has(c.parent_id)).map((c) => c.id));
  for (const o of ops) {
    const touched = (o as any).id as string | undefined;
    if (touched && o.op !== "update-role" && o.op !== "update-everyone" && o.op !== "bind") {
      assert.ok(!bridge.has(touched) && !bridgeChildren.has(touched), `${o.op} touches bridge ${touched}`);
    }
  }
  assert.ok(!ops.some((o) => /delete/i.test(o.op)));
  assert.match(renderPlan(ops), /Nothing is deleted/);
});

test("existing roles are reused by setting id (members keep them); Staff is renamed, not recreated", () => {
  const { ops, settings } = plan();
  const staffUpdate = ops.find((o) => o.op === "update-role" && o.id === settings.discord_role_staff_id) as any;
  assert.ok(staffUpdate, "staff role updated in place");
  assert.equal(staffUpdate.body.name, "⚙️ Nxeon Team");
  assert.ok(!ops.some((o) => o.op === "create-role" && /Verified|Owner|Admin|Staff|Support/.test((o as any).body.name)));
});

test("SECURITY: no customer, ping or game role gets a dangerous permission; @everyone loses invite/@everyone/private threads", () => {
  for (const r of NXEON_SERVER_SPEC.roles) {
    if (["owner", "admin", "manager", "moderator", "support", "bots"].includes(r.key)) continue;
    const bad = r.permissions.filter((p) => (DANGEROUS as readonly string[]).includes(p));
    assert.deepEqual(bad, [], `${r.key} must not hold ${bad.join(",")}`);
  }
  const base = namesOf(bits(NXEON_SERVER_SPEC.everyone));
  for (const p of ["MENTION_EVERYONE", "CREATE_INSTANT_INVITE", "CREATE_PRIVATE_THREADS", "ADMINISTRATOR", "MANAGE_MESSAGES"]) assert.ok(!base.includes(p as any), p);
  // today every badge role can @everyone the whole server; the plan must strip it
  const { ops, settings } = plan();
  const verified = ops.find((o) => o.op === "update-role" && o.id === settings.discord_role_verified_id) as any;
  assert.ok(!namesOf(verified.body.permissions).includes("MENTION_EVERYONE"));
});

test("LEAK GUARD: every private category/channel denies @everyone VIEW_CHANNEL", () => {
  const { ops } = plan();
  for (const ref of ["$cat:desk", "$cat:staff", "$cat:management", "$cat:customers", "$legacy", "$ch:tickets", "$ch:creators", "$ch:g_minecraft"]) {
    const wire = wireOf(ops, ref);
    assert.ok(wire, `${ref} has overwrites in the plan`);
    const everyone = wire!.find((o) => o.id === G);
    assert.ok(everyone && (BigInt(everyone.deny) & 1024n) === 1024n, `${ref} must deny @everyone VIEW_CHANNEL`);
  }
});

test("#tickets: customers can read their threads but cannot type, start threads or post; support can manage threads", () => {
  const { ops, settings } = plan();
  const wire = wireOf(ops, "$ch:tickets")!;
  const verified = wire.find((o) => o.id === `$role:verified` || o.id === settings.discord_role_verified_id)!;
  const deny = namesOf(verified.deny);
  for (const p of ["SEND_MESSAGES", "SEND_MESSAGES_IN_THREADS", "CREATE_PRIVATE_THREADS", "CREATE_PUBLIC_THREADS"]) assert.ok(deny.includes(p as any), p);
  assert.ok(namesOf(verified.allow).includes("VIEW_CHANNEL"));
  const support = wire.find((o) => o.id === "$role:support")!;
  assert.ok(namesOf(support.allow).includes("MANAGE_THREADS"));
});

test("text channels that must become forums are replaced, the old one is kept read-only in Legacy", () => {
  const { ops } = plan();
  const legacy = ops.filter((o) => o.op === "move-to-legacy").map((o: any) => o.name);
  assert.ok(legacy.includes("support-help"));
  assert.ok(legacy.includes("showcase"));
  assert.ok(ops.some((o) => o.op === "create-channel" && (o as any).body.name === "community-help" && (o as any).body.type === 15));
  // text -> announcement converts in place
  assert.ok(ops.some((o) => o.op === "update-channel" && o.ref === "$ch:announcements" && o.changes.includes("type 0 -> 5")));
});

test("apply against a fake guild succeeds, posts the panels, writes the settings, and a re-plan is a no-op", async () => {
  const { ops, guild, settings } = plan();
  const fake = fakeDiscord(guild);
  const res = await executeRedoPlan(ops, {
    guildId: G,
    botRoleId: BOT,
