  assert.equal(fake.calls.filter((c) => /\/messages$/.test(c.path)).length, 3, "rules, link-account, open-a-ticket panels");
  assert.match(settings.discord_channel_ticket_desk_id, /^\d+$/);
  assert.match(settings.discord_channel_chat_desk_id, /^\d+$/);
  assert.match(settings.discord_role_moderator_id, /^\d+$/);

  const again = planServerRedo({ spec: NXEON_SERVER_SPEC, guild, settings, botRoleId: BOT });
  const work = again.filter((o) => ["create-role", "update-role", "create-category", "create-channel", "update-channel", "move-to-legacy", "set-setting", "update-everyone"].includes(o.op));
  assert.deepEqual(work, [], `second run should change nothing, got: ${JSON.stringify(work).slice(0, 400)}`);
});

