import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { bridgeThreadName, chooseBridgeMode, isThreadType, staffToAutoAdd } from "../lib/discord-thread-plan.ts";
import { replyEchoText, resolveDiscordTicketReplyActor } from "../lib/discord-bridge.ts";

/** Bridge thread mode + customer replies from Discord (server redo, 2026-10-07). */

test("thread mode needs BOTH the setting and a host channel id; anything else stays on channels", () => {
  assert.equal(chooseBridgeMode("threads", "1556000000000000001"), "threads");
  assert.equal(chooseBridgeMode("THREADS ", "1556000000000000001"), "threads");
  assert.equal(chooseBridgeMode("threads", ""), "channels");
  assert.equal(chooseBridgeMode("threads", "not-an-id"), "channels");
  assert.equal(chooseBridgeMode("channels", "1556000000000000001"), "channels");
  assert.equal(chooseBridgeMode(undefined, undefined), "channels");
});

test("thread names: short id first, one line, max 100 chars", () => {
  assert.equal(bridgeThreadName("ticket", "cmuti1r0wefymhlkvrnj4pe16", "Server won't\nstart"), "ticket-vrnj4pe16".replace("ticket-vrnj4pe16", "ticket-nj4pe16".length ? `ticket-${"cmuti1r0wefymhlkvrnj4pe16".slice(-8)} · Server won't start` : ""));
  assert.equal(bridgeThreadName("chat", "abcdefgh12345678"), "chat-12345678");
  assert.ok(bridgeThreadName("ticket", "x".repeat(30), "y".repeat(300)).length <= 100);
});

test("isThreadType", () => {
  assert.ok(isThreadType(12) && isThreadType(11) && isThreadType(10));
  assert.ok(!isThreadType(0) && !isThreadType(4) && !isThreadType(null));
});

test("auto-added staff: linked, not suspended, support-capable, de-duplicated, capped", () => {
  const canSupport = (r: string) => r === "SUPPORT" || r === "ADMIN";
  const out = staffToAutoAdd(
    [
      { discordUserId: "1", role: "ADMIN" },
      { discordUserId: null, role: "SUPPORT" },
      { discordUserId: "2", role: "BILLING" },
      { discordUserId: "3", role: "SUPPORT", suspended: true },
      { discordUserId: "1", role: "SUPPORT" },
      { discordUserId: "4", role: "SUPPORT" },
    ],
    canSupport,
  );
  assert.deepEqual(out, ["1", "4"]);
  const many = Array.from({ length: 20 }, (_, i) => ({ discordUserId: String(i + 10), role: "SUPPORT" }));
  assert.equal(staffToAutoAdd(many, canSupport).length, 8);
});

test("ticket replies from Discord: the ticket's own customer replies AS CUSTOMER, staff AS STAFF, others rejected", () => {
  assert.deepEqual(resolveDiscordTicketReplyActor({ id: "cust1", role: "CUSTOMER" as any }, "cust1"), { actorId: "cust1", asStaff: false });
  assert.deepEqual(resolveDiscordTicketReplyActor({ id: "sup1", role: "SUPPORT" as any }, "cust1"), { actorId: "sup1", asStaff: true });
  const other = resolveDiscordTicketReplyActor({ id: "cust2", role: "CUSTOMER" as any }, "cust1");
  assert.ok("error" in other, "a different customer can never reply on someone else's ticket");
  assert.ok("error" in resolveDiscordTicketReplyActor(null, "cust1"));
  assert.ok("error" in resolveDiscordTicketReplyActor({ id: "cust1", role: "CUSTOMER" as any, suspended: true }, "cust1"));
  // a staff member's OWN ticket: they reply as its customer (same override as writeTicketReply)
  assert.deepEqual(resolveDiscordTicketReplyActor({ id: "sup1", role: "SUPPORT" as any }, "sup1"), { actorId: "sup1", asStaff: false });
});

test("the echoed reply is the Discord transcript line", () => {
  assert.equal(replyEchoText(true, "Sam", "On it"), "🛟 **Staff (Sam)**: On it");
  assert.equal(replyEchoText(false, "Alice", "thanks"), "👤 **Customer**: thanks", "customer name is not repeated publicly");
  assert.ok(replyEchoText(true, null, "x".repeat(5000)).length <= 2000);
});

// --- wiring guards ---------------------------------------------------------------
const root = join(import.meta.dirname, "..");
const bridge = readFileSync(join(root, "lib/discord-bridge.ts"), "utf8");
const route = readFileSync(join(root, "app/api/webhooks/discord/route.ts"), "utf8");
const discord = readFileSync(join(root, "lib/discord.ts"), "utf8");

test("WIRING: both ensure* paths branch on thread mode, and live chats never add the customer to a staff-only thread", () => {
  assert.match(bridge, /bridgeModeFor\("ticket"\)/);
  assert.match(bridge, /bridgeModeFor\("chat"\)/);
  assert.match(bridge, /if \(convo\.userId && mode !== "threads"\) await grantCustomerAccessAndSummary/);
  assert.match(bridge, /setThreadArchivedIfThread\(discordThreadId, archived\)/);
});

test("WIRING: the #open-a-ticket button uses the same linked-account gate as /support", () => {
  const i = route.indexOf('customId === "dc_open_ticket"');
  assert.ok(i > 0);
  assert.match(route.slice(i, i + 300), /canOpenTicketFromDiscord/);
  assert.match(route, /ackText\.startsWith\("⚠️"\)\) return NextResponse\.json\(ephemeralMessageResponse/);
});

test("WIRING: mirrored text can never ping (@everyone / roles)", () => {
  const i = discord.indexOf("export async function postChannelMessage(");
  assert.match(discord.slice(i, i + 900), /allowed_mentions: \{ parse: \[\] \}/);
  assert.match(discord, /allowed_mentions: \{ parse: \[\], roles: msg\.allowedRoleMentions \?\? \[\] \}/);
});
EOF
