import { test } from "node:test";
import assert from "node:assert/strict";
import {
  BRAND,
  incidentEmbed,
  linkAccountPanel,
  nextWatermark,
  openTicketPanel,
  queuePing,
  releasesToPost,
  rulesPanel,
  welcomePanel,
  whatsNewEmbed,
  type ReleaseLike,
} from "../lib/discord-embeds.ts";

/** Public status feed, What's New auto-post, redo panels, staff queue ping. */

const APP = "https://nxeon.cloud";
const now = new Date("2026-10-07T12:00:00Z");

test("status embed: colour by severity, resolved is green, links the public status page", () => {
  const down = incidentEmbed({ title: "Game servers in Singapore", severity: "down", component: "sgp1", body: "Investigating." }, "opened", APP, now);
  assert.equal(down.color, BRAND.red);
  assert.match(down.title!, /^Outage: /);
  assert.equal(down.url, `${APP}/status`);
  const fixed = incidentEmbed({ title: "Game servers in Singapore", severity: "down" }, "resolved", APP, now);
  assert.equal(fixed.color, BRAND.green);
  assert.match(fixed.title!, /^Resolved: /);
  assert.equal(fixed.fields![0].value, "Platform-wide");
});

const rel = (o: Partial<ReleaseLike>): ReleaseLike => ({
  id: o.id ?? "r",
  title: o.title ?? "Release",
  status: o.status ?? "PUBLISHED",
  publishedAt: o.publishedAt ?? null,
  scheduledFor: o.scheduledFor ?? null,
  createdAt: o.createdAt ?? new Date("2026-10-01T00:00:00Z"),
  audience: o.audience ?? "ALL",
  regions: o.regions ?? [],
  serviceTypes: o.serviceTypes ?? [],
  highlights: o.highlights,
  summary: o.summary,
});

test("What's New: only live, untargeted releases after the watermark, oldest first", () => {
  const wm = new Date("2026-10-05T00:00:00Z");
  const rows = [
    rel({ id: "old", publishedAt: new Date("2026-10-04T00:00:00Z") }),
    rel({ id: "b", publishedAt: new Date("2026-10-07T10:00:00Z") }),
    rel({ id: "a", publishedAt: new Date("2026-10-06T10:00:00Z") }),
    rel({ id: "game-only", publishedAt: new Date("2026-10-06T11:00:00Z"), audience: "GAME" }),
    rel({ id: "sgp-only", publishedAt: new Date("2026-10-06T11:00:00Z"), regions: ["sgp1"] }),
    rel({ id: "legacy-scoped", publishedAt: new Date("2026-10-06T11:00:00Z"), serviceTypes: ["VPS"] }),
    rel({ id: "draft", status: "DRAFT" }),
    rel({ id: "future", status: "SCHEDULED", scheduledFor: new Date("2026-10-08T00:00:00Z") }),
    rel({ id: "due", status: "SCHEDULED", scheduledFor: new Date("2026-10-07T11:00:00Z") }),
  ];
  assert.deepEqual(releasesToPost(rows, wm, now).map((r) => r.id), ["a", "b", "due"]);
  assert.deepEqual(releasesToPost(rows, wm, now, 2).map((r) => r.id), ["a", "b"]);
  // watermark moves past skipped targeted releases too, but never into the future
  assert.equal(nextWatermark(rows, wm, now).toISOString(), "2026-10-07T11:00:00.000Z");
});

test("What's New embed: highlights become fields; relative hero image is made absolute", () => {
  const e = whatsNewEmbed(
    { ...rel({ id: "x", publishedAt: now, highlights: [{ title: "Live chat", description: "Real-time replies." }] }), heroImageUrl: "/whats-new/x.webp" },
    APP,
  );
  assert.equal(e.fields![0].name, "Live chat");
  assert.equal(e.image!.url, `${APP}/whats-new/x.webp`);
  assert.equal(whatsNewEmbed({ ...rel({ publishedAt: now }), heroImageUrl: "https://evil.example/x.png" }, APP).image, undefined);
});

test("panels: open-a-ticket button id matches the webhook handler; link buttons point at real portal pages", () => {
  const p = openTicketPanel(APP);
  const buttons = (p.components[0] as any).components;
  assert.equal(buttons[0].custom_id, "dc_open_ticket");
  assert.equal(buttons[1].url, `${APP}/dashboard/support`);
  assert.equal((linkAccountPanel(APP).components[0] as any).components[0].url, `${APP}/dashboard/settings?tab=integrations`);
  assert.match(rulesPanel().embeds[0].description!, /Never share passwords/);
  const w = JSON.stringify(welcomePanel(APP));
  assert.ok(!/\/docs/.test(w), "public /docs is retired");
});

test("BRAND VOICE: no public copy names a third-party infrastructure provider", () => {
  const all = JSON.stringify([openTicketPanel(APP), linkAccountPanel(APP), rulesPanel(), welcomePanel(APP)]);
  assert.ok(!/\b(OVH|Hetzner|Proxmox|provider)\b/i.test(all));
});

test("queue ping mentions ONLY the support role, and links the private thread", () => {
  const p = queuePing({ kind: "ticket", threadId: "123", subject: "Help", priority: "HIGH", supportRoleId: "777", appUrl: APP, adminPath: "/admin/support/t1" });
  assert.match(p.content, /^<@&777> 🎫 New ticket <#123> · \*\*Help\*\* · HIGH/);
  assert.deepEqual(p.allowedRoleMentions, ["777"]);
  const q = queuePing({ kind: "chat", threadId: "9", appUrl: APP, adminPath: "/admin/chat" });
  assert.deepEqual(q.allowedRoleMentions, []);
});
EOF
