+import { createBridgeChannel, moveBridgeChannel, notifySupportQueueFallback } from "./discord-category-pool";
+import { kickDiscordHousekeeping } from "./discord-housekeeping";
+import { addThreadMember, bridgeModeFor, openBridgeThread, setThreadArchivedIfThread } from "./discord-threads";
 import { writeTicketReply, writeChatReply, createTicketCore } from "./reply-core";

 /** VIEW_CHANNEL + SEND_MESSAGES + READ_MESSAGE_HISTORY, OR'd as a single Discord permission bitfield string. */
@@ -27,7 +29,7 @@ const CUSTOMER_CHANNEL_ACCESS = (
